```python
import sys

def add_quotes_around_table_column_names(file_path):
    with open(file_path, 'r') as file:
        sql_statement = file.read()

    quoted_sql_statement = quote_table_column_names(sql_statement)
    return quoted_sql_statement

def quote_table_column_names(sql_statement):
    quoted_sql_statement = ''
    in_string = False
    for char in sql_statement:
        if char == '"':
            in_string = not in_string
        elif in_string or (char == ' ' and not in_string):
            quoted_sql_statement += char
        else:
            if in_string:
                quoted_sql_statement += char
            else:
                if char == ' ':
                    quoted_sql_statement += '""'
                else:
                    quoted_sql_statement += char
                in_string = True
    return quoted_sql_statement

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python sql_quote.py <path_to_sql_file>")
        sys.exit(1)

    file_path = sys.argv[1]
    quoted_sql_statement = add_quotes_around_table_column_names(file_path)
    print("Modified SQL statement with double quotes around table and column names:")
    print(quoted_sql_statement)
```
