private fun convertSnapshotToReport(document: QueryDocumentSnapshot): Report {
    val title = document.getString("title") ?: ""
    val dataMap = document.data as? Map<String, Any> ?: emptyMap()
    val dataList = dataMap.map { (key, value) ->
        Entry(key.toFloat(), value as Float)
    }.sortedBy { it.x }
    return Report(title, dataList)
}

fun getReports(timePeriod: TimePeriod, callback: (List<Report>) -> Unit) {
    db.collection(timePeriod.toString().toLowerCase()).get()
        .addOnSuccessListener { querySnapshot ->
            val reports = querySnapshot.map { document ->
                convertSnapshotToReport(document)
            }
            callback(reports)
        }
        .addOnFailureListener {
            callback(emptyList())
        }
}
