extern int Max_MA_Range = 10;

int MA1_Period = 3;
int MA2_Period = 6;
int MA3_Period = 9;

double MA1_Buffer[];
double MA2_Buffer[];
double MA3_Buffer[];

//+------------------------------------------------------------------+
