```kotlin
class FlashcardAdapter(private val flashcards: List<Flashcard>, private val onItemClick: (Flashcard) -> Unit) :
    RecyclerView.Adapter<FlashcardAdapter.FlashcardViewHolder>() {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): FlashcardViewHolder {
        val view = LayoutInflater.from(parent.context).inflate(R.layout.flashcard_item, parent, false)
        return FlashcardViewHolder(view)
    }

    override fun getItemCount(): Int {
        return flashcards.size
    }

    override fun onBindViewHolder(holder: FlashcardViewHolder, position: Int) {
        holder.bind(flashcards[position], onItemClick)
    }

    class FlashcardViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        private val frontTextView: TextView = itemView.findViewById(R.id.flashcard_front)

        fun bind(flashcard: Flashcard, onItemClick: (Flashcard) -> Unit) {
            frontTextView.text = flashcard.front
            itemView.setOnClickListener { onItemClick(flashcard) }
        }
    }
}
