import java.text.DecimalFormat;
import java.util.Scanner;

public class GasStation {
    private final int numPumps;
    private final Pump[] pumps;

    public GasStation(int numPumps) {
        this.numPumps = numPumps;
        this.pumps = new Pump[numPumps];
        for (int i = 0; i < numPumps; i++) {
            pumps[i] = new Pump(i + 1);
        }
    }

    public void serveCustomer(Customer customer) {
        System.out.println("Customer " + customer.id + " paying $" + customer.payment + " for gas.");
        Pump selectedPump = findAvailablePump();
        if (selectedPump == null) {
            System.out.println("Error: No available pump for customer " + customer.id + ".");
            return;
        }

        selectedPump.activate(customer);
    }

    private Pump findAvailablePump() {
        for (Pump pump : pumps) {
            if (!pump.busy) {
                return pump;
            }
        }
        return null;
    }

    public static void main(String[] args) {
        GasStation gasStation = new GasStation(3);
        Customer[] customers = new Customer[]{
                new Customer(1, 10),
                new Customer(2, 5)
        };
        for (Customer customer : customers) {
            gasStation.serveCustomer(customer);
        }
    }

    private static class Pump {
        private final int id;
        private boolean busy;

        public Pump(int id) {
            this.id = id;
            this.busy = false;
        }

        public void activate(Customer customer) {
            this.busy = true;
            System.out.println("Pump " + id + " activated for customer " + customer.id + ".");
            double providedGas = customer.payment / 2;
            DecimalFormat decimalFormat = new DecimalFormat("#.##");
            System.out.println("Pump " + id + " delivers $" + decimalFormat.format(providedGas) + " of gas to customer " + customer.id + ".");
            if (Math.abs(providedGas - customer.payment) > 0.01) {
                System.out.println("Error: Customer " + customer.id + " not satisfied. Incorrect amount of gas delivered.");
            }
            this.busy = false;
        }
    }

    private static class Customer {
        private final int id;
        private final double payment;

        public Customer(int id, double payment) {
            this.id = id;
            this.payment = payment;
        }
    }
}
