        for (int i = 0; i < level.lines.Size(); i++)
        {
            Line lline = level.lines[i];

            if (lline.special == exitLineSpecial)
            {
	            lline.flags &= ~Line.ML_BLOCKING; // Unblock the line
            }
        }
    }
}

