Sure, here's the complete code for the genetic algorithm to optimize your monthly budgeting app.

```go
package main

import (
	"fmt"
	"math/rand"
	"sort"
	"time"
)

type Chromosome struct {
	Alleles []float64
	Fitness float64
}

type Expenses struct {
	Fixed    []float64
	Variable []float64
	Priority []int
	Budget   float64
}

type Config struct {
	PopulationSize int
	Generations    int
	MutationRate   float64
}

func main() {
	expenses := Expenses{
		Fixed:    []float64{500, 300, 200},
		Variable: []float64{400, 100, 200, 50, 120},
		Priority: []int{4, 2, 3, 5, 1},
		Budget:   1500,
	}

	config := Config{
		PopulationSize: 100,
		Generations:    1000,
		MutationRate:   0.1,
	}

	chrom := geneticAlgorithm(expenses, config)
	fmt.Printf("Best chromosome: %#v\n", chrom)
}

func geneticAlgorithm(exp Expenses, conf Config) Chromosome {
	rand.Seed(time.Now().UnixNano())

	population := initializePopulation(conf.PopulationSize, len(exp.Variable))

	for i := 0; i < len(population); i++ {
		population[i].Fitness = calcFitness(population[i], exp)
	}

	for gen := 0; gen < conf.Generations; gen++ {
		newPopulation := make([]Chromosome, 0, conf.PopulationSize)

		for i := 0; i < conf.PopulationSize; i++ {
			parent1 := selectParent(population)
			parent2 := selectParent(population)

			child := crossover(parent1, parent2)
			mutate(child, conf.MutationRate)

			child.Fitness = calcFitness(child, exp)
			newPopulation = append(newPopulation, child)
		}

		population = newPopulation
	}

	best := findBestChromosome(population)
	return best
}

func calcFitness(chr Chromosome, exp Expenses) float64 {
	totalFixedExp := 0.0
	for _, e := range exp.Fixed {
		totalFixedExp += e
	}
	totalVariableExp := 0.0
	for i, e := range chr.Alleles {
		totalVariableExp += e * exp.Variable[i]
	}
	totalExp := totalFixedExp + totalVariableExp
	diff := exp.Budget - totalExp
	if diff >= 0 {
		return diff
	}

	penalty := -5.0 * diff
	for i, allele := range chr.Alleles {
		penalty -= allele * float64(exp.Priority[i])
	}

	return penalty
}

func initializePopulation(populationSize, numVariables int) []Chromosome {
	population := make([]Chromosome, populationSize)

	for i := 0; i < populationSize; i++ {
		chrom := Chromosome{
			Alleles: make([]float64, numVariables),
		}

		for j := 0; j < numVariables; j++ {
			chrom.Alleles[j] = rand.Float64()
		}

		population[i] = chrom
	}

	return population
}

func selectParent(population []Chromosome) Chromosome {
	// Tournament selection with size 2
	idx1 := rand.Intn(len(population))
	idx2 := rand.Intn(len(population))

	if population[idx1].Fitness >= population[idx2].Fitness {
		return population[idx1]
	}

	return population[idx2]
}

func crossover(parent1, parent2 Chromosome) Chromosome {
	child := Chromosome{
		Alleles: make([]float64, len(parent1.Alleles)),
	}

	crossoverPoint := rand.Intn(len(parent1.Alleles))

	for i := 0; i < len(parent1.Alleles); i++ {
		if i < crossoverPoint {
			child.Alleles[i] = parent1.Alleles[i]
		} else {
			child.Alleles[i] = parent2.Alleles[i]
		}
	}

	return child
}

func mutate(chr Chromosome, mutationRate float64) {
	for i := 0; i < len(chr.Alleles); i++ {
		if rand.Float64() <= mutationRate {
			chr.Alleles[i] = rand.Float64()
		}
	}
}

func findBestChromosome(population []Chromosome) Chromosome {
	best := population[0]

	for _, chr := range population {
		if chr.Fitness > best.Fitness {
			best = chr
		}
	}

	return best
}
```
