   ```javascript
   const getCurrentPercentage = () => {
     if (!liveCandleData || liveCandleData.length === 0 || !openPrice) {
       return 0;
     }
     const latestPrice = liveCandleData[liveCandleData.length - 1].close;
     const percentage = ((latestPrice - openPrice) / openPrice) * 100;
     return percentage;
   };
