panic: oto: NewContext can be called only once

The error you're encountering (`panic: oto: NewContext can be called only once`) is because oto only allows one instance of a context to play audio. You're trying to create a new oto context every time you play the audio file, which causes the error.

To fix this issue, create an oto context once, and then use it repeatedly for playing and stopping the file.

Here's a modification of your code that solves the issue:

```go
package main

import (
    "io"
    "os"
    "sync"
    "gioui.org/app"
    "gioui.org/io/system"
    "gioui.org/layout"
    "gioui.org/op"
    "gioui.org/unit"
    "gioui.org/widget"
    "gioui.org/widget/material"
    "gioui.org/font/gofont"

    "github.com/tosone/minimp3"
    "github.com/hajimehoshi/oto"
)

func main() {
    go func() {
        w := app.NewWindow(
            app.Title("mp3 reader"),
            app.Size(unit.Dp(350), unit.Dp(500)),
        )

        var ops op.Ops
        for event := range w.Events() {
            switch event := event.(type) {
            case system.DestroyEvent:
                os.Exit(0)
            case system.FrameEvent:
                event.Frame(frame(layout.NewContext(&ops, event)))
            }
        }
    }()
    app.Main()
}

type (
    // C quick alias for Context.
    C = layout.Context
    // D quick alias for Dimensions.
    D = layout.Dimensions
)

var (
    th      = material.NewTheme(gofont.Collection())
    topLabel = "mp3 reader"
    playBtn  = widget.Clickable{}
    stopBtn  = widget.Clickable{}
    playing  bool
    mu       sync.Mutex
    player   *oto.Player
    dec      *minimp3.Decoder
)

// frame lays out the entire frame and returns the resultant ops buffer.
func frame(gtx C) *op.Ops {

    layout.Center.Layout(gtx, func(gtx C) D {

        gtx.Constraints.Max.X = gtx.Dp(unit.Dp(300))
        return layout.Flex{Axis: layout.Vertical}.Layout(gtx,
            layout.Rigid(func(gtx C) D {
                label := material.H5(th, topLabel)
                return label.Layout(gtx)
            }),
            layout.Rigid(func(gtx C) D {
                return material.Button(th, &playBtn, "Play").Layout(gtx)
            }),
