				inset := layout.Inset{Right: unit.Dp(20)}
				return inset.Layout(gtx, func(gtx C) D {
					return material.Button(th, &playBtn, "Play").Layout(gtx)
				})
			}),
			layout.Rigid(func(gtx C) D {
				inset := layout.Inset{Right: unit.Dp(20)}
				return inset.Layout(gtx, func(gtx C) D {
					return material.Button(th, &pauseBtn, pauseState).Layout(gtx)
				})
			}),
			layout.Rigid(func(gtx C) D {
				return material.Button(th, &stopBtn, "Stop").Layout(gtx)
			}),
		)
	})

	if playBtn.Clicked() {
		go func() {
			if isStopped {
				isStopped = false
				var err error
				var response *http.Response
				if response, err = http.Get(url); err != nil {
					log.Fatal(err)
				}

				d, err := mp3.NewDecoder(response.Body)
				if err != nil {
					return
				}

				c, ready, err := oto.NewContext(d.SampleRate(), 2, 2)
				if err != nil {
					return
				}
				<-ready

				player = c.NewPlayer(d)
				defer func() {
					player.Close()
					response.Body.Close()
				}()

				player.Play()

				for {
					time.Sleep(time.Second)
					if !player.IsPlaying() && !isPaused {
						break
					}
				}
			}
		}()
	}

	if pauseBtn.Clicked() {
		if !isStopped {
			if isPaused {
				player.Play()
				isPaused = false
				pauseState = "Pause"
			} else {
				player.Pause()
				isPaused = true
				pauseState = "Resume"
			}
		}
	}

	if stopBtn.Clicked() {
		if player != nil && !isStopped {
			player.Stop()
			isStopped = true
		}
	}
	return gtx.Ops
}
