        )

        var ops op.Ops
        for event := range w.Events() {
            switch event := event.(type) {
            case system.DestroyEvent:
                os.Exit(0)
            case system.FrameEvent:
                event.Frame(frame(layout.NewContext(&ops, event)))
            }
        }
    }()
    app.Main()
}

type (
    // C quick alias for Context.
    C = layout.Context
    // D quick alias for Dimensions.
    D = layout.Dimensions
)

var (
    th        = material.NewTheme(gofont.Collection())
    topLabel  = "mp3 reader"
    playBtn   = widget.Clickable{}
    pauseBtn  = widget.Clickable{}
    stopBtn   = widget.Clickable{}
    url       = "https://qurango.net/radio/ahmad_khader_altarabulsi"
    player    *oto.Player
    decoder   *mp3.Decoder
    response  *http.Response
    playing   bool
)

// frame lays out the entire frame and returns the resultant ops buffer.
func frame(gtx C) *op.Ops {

    layout.Center.Layout(gtx, func(gtx C) D {

        gtx.Constraints.Max.X = gtx.Dp(unit.Dp(300))
        return layout.Flex{Axis: layout.Vertical}.Layout(gtx,
            layout.Rigid(func(gtx C) D {
                label := material.H5(th, topLabel)
                return label.Layout(gtx)
            }),
            layout.Rigid(func(gtx C) D {
                return material.Button(th, &playBtn, "Play").Layout(gtx)
            }),
            layout.Rigid(func(gtx C) D {
                return material.Button(th, &pauseBtn, "Pause").Layout(gtx)
            }),
            layout.Rigid(func(gtx C) D {
                return material.Button(th, &stopBtn, "Stop").Layout(gtx)
            }),
        )
    })

    if playBtn.Clicked() {
        go playAudio()
    }
    if pauseBtn.Clicked() {
        pauseAudio()
    }
    if stopBtn.Clicked() {
        stopAudio()
    }
    return gtx.Ops
}

func playAudio() {
    var err error
    if response, err = http.Get(url); err != nil {
        log.Fatal(err)
    }

    decoder, err = mp3.NewDecoder(response.Body)
    if err != nil {
        log.Fatal(err)
    }

    context, ready, err := oto.NewContext(decoder.SampleRate(), 2, 2)
    if err != nil {
        log.Fatal(err)
    }
    <-ready

    player = context.NewPlayer(decoder)
    player.Play()

    playing = true
    for playing {
        select {
        case _, ok := <-player.Done():
            if !ok {
                playing = false
            }
        default:
        }
        time.Sleep(time.Millisecond * 100)
    }
}

func pauseAudio() {
    if player != nil {
        player.Pause()
    }
}

func stopAudio() {
    if player != nil {
        player.Close()
        decoder.Close()
        response.Body.Close()
        player = nil
        playing = false
    }
} 

We added three new clickable widgets for the pause and stop buttons, and also added some global variables to keep track of the player, decoder, and response objects. The playAudio function is modified to store a reference to the player object and set the playing variable to true, which is used by other button click handlers to check if audio playback is ongoing.

The pauseAudio function simply calls the Pause method on the player object, and the stopAudio function cleans up all the objects and sets the playing variable to false.

Now we have a fully functional MP3 player with play, pause, and stop buttons.

