using System.Windows.Forms;

namespace WindowsFormsApp1
{
    public partial class Form1 : Form
    {
        SqlConnection connection = new SqlConnection("Data Source=SERVERNAME;Initial Catalog=DATABASENAME;User ID=USERNAME;Password=PASSWORD;");
        // Replace SERVERNAME, DATABASENAME, USERNAME, and PASSWORD with the appropriate values for your database connection
        SqlCommand command;
        SqlDataReader reader;
        DataTable dataTable;

        public Form1()
        {
            InitializeComponent();
        }

        private void Form1_Load(object sender, EventArgs e)
        {
            string query = "SELECT * FROM tablename";
            command = new SqlCommand(query, connection);
            dataTable = new DataTable();

            try
            {
                connection.Open();
                reader = command.ExecuteReader();
                dataTable.Load(reader);
                dataGridView1.DataSource = dataTable;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
            }
            finally
            {
                connection.Close();
                reader.Close();
            }
        }
    }
}
