uint8_t quantize_color_to_palette(uint8_t in_r, uint8_t in_g, uint8_t in_b, uint8_t palette[16][3]) {
    uint32_t min_distance = 0xFFFFFFFF;
    unsigned index = 0;
    for (unsigned i = 0; i < 16; ++i) {
        uint32_t dr = abs(in_r - palette[i][0]);
        uint32_t dg = abs(in_g - palette[i][1]);
        uint32_t db = abs(in_b - palette[i][2]);

        uint32_t distance = dr * dr + dg * dg + db * db;

        if (distance < min_distance) {
            min_distance = distance;
            index = i;
        }
    }
    return index;
}

