  const deck = shuffleDeck();
  const players = playerNames.map(name => ({ name, hand: [] }));
  const game = new Game({ players, deck, currentPlayer: players[0].name });
  await game.save();
  return game;
};

// deal a hand of 13 cards to each player
const dealHands = async (game) => {
  const { players, deck } = game;
  for (let i = 0; i < 13; i++) {
    for (let j = 0; j < players.length; j++) {
      const card = deck.pop();
      players[j].hand.push(card);
    }
  }
  game.deck = deck;
  await game.save();
};

// play a card from the given player's hand in the current trick
const playCard = async (game, playerName, cardCode) => {
  const { players, rounds, currentPlayer } = game;
  const round = rounds[rounds.length - 1];
  const trick = round.tricks[round.tricks.length - 1];
  const playerIndex = players.findIndex(p => p.name === playerName);
  const cardIndex = players[playerIndex].hand.findIndex(c => c === cardCode);
  const card = players[playerIndex].hand.splice(cardIndex, 1)[0];
  trick.cards.push(card);
  if (trick.cards.length === players.length) {
    trick.winner = getTrickWinner(trick.cards, currentPlayer);
    game.currentPlayer = trick.winner;
    round.tricks.push({ cards: [], winner: null });
  } else {
    game.currentPlayer = players[(playerIndex + 1) % players.length].name;
  }
  await game.save();
};

// get the current state of the game (hands, tricks, etc.)
const getGameState = async (game) => {
  const { players, rounds } = game;
  const gameState = { players: [], rounds: [] };
  for (let i = 0; i < players.length; i++) {
    gameState.players.push({ name: players[i].name, hand: players[i].hand });
  }
  for (let i = 0; i < rounds.length; i++) {
    const roundState = { number: rounds[i].number, tricks: [] };
    for (let j = 0; j < rounds[i].tricks.length; j++) {
      const trickState = { cards: rounds[i].tricks[j].cards, winner: rounds[i].tricks[j].winner };
      roundState.tricks.push(trickState);
    }
    gameState.rounds.push(roundState);
  }
  return gameState;
};
