以下是使用Apache Flink访问MySQL数据库的基本示例代码：

```java
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.java.DataSet;
import org.apache.flink.api.java.ExecutionEnvironment;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.connector.jdbc.JdbcConnectionOptions;
import org.apache.flink.connector.jdbc.JdbcInputFormat;
import org.apache.flink.connector.jdbc.JdbcOutputFormat;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.types.Row;
import java.sql.PreparedStatement;
import java.util.Properties;

public class FlinkMySQLExample {

    public static void main(String[] args) throws Exception {

        // 执行批处理
        batchProcessing();

        // 执行流处理
        streamProcessing();
    }

    public static void batchProcessing() throws Exception {
        // 创建执行环境
        ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();

        //配置连接参数
        final Properties props = new Properties();
        props.setProperty("driver", "com.mysql.jdbc.Driver");
        props.setProperty("url", "jdbc:mysql://localhost:3306/test");
        props.setProperty("username", "root");
        props.setProperty("password", "root");

        //创建JDBC输入格式
        JdbcInputFormat inputFormat = JdbcInputFormat.buildJdbcInputFormat()
                .setDBUrl(props.getProperty("url"))
                .setDrivername(props.getProperty("driver"))
                .setUsername(props.getProperty("username"))
                .setPassword(props.getProperty("password"))
                .setQuery("SELECT * FROM student")
                .setRowTypeInfo(null) //设置类型信息
                .finish();

        //读取数据
        DataSet<Row> rowData = env.createInput(inputFormat);

        //将数据map为tuple2
        DataSet<Tuple2<Integer, String>> resultSet = rowData.map(new MapFunction<Row, Tuple2<Integer, String>>() {
            @Override
            public Tuple2<Integer, String> map(Row row) throws Exception {
                return Tuple2.of((Integer) row.getField(0), row.getField(1).toString());
            }
        });

        //输出结果
        resultSet.print();
    }

    public static void streamProcessing() throws Exception {
        // 创建执行环境
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        //配置连接参数
        final Properties props = new Properties();
        props.setProperty("driver", "com.mysql.jdbc.Driver");
        props.setProperty("url", "jdbc:mysql://localhost:3306/test");
        props.setProperty("username", "root");
        props.setProperty("password", "root");

        //创建JDBC输入格式
        JdbcInputFormat inputFormat = JdbcInputFormat.buildJdbcInputFormat()
                .setDBUrl(props.getProperty("url"))
                .setDrivername(props.getProperty("driver"))
                .setUsername(props.getProperty("username"))
                .setPassword(props.getProperty("password"))
                .setQuery("SELECT * FROM student WHERE id > ?") //占位符
                .setRowTypeInfo(null) //设置类型信息
                .setParameterTypes(int.class) //设置占位符类型
                .finish();

        //创建数据源
        DataSet<Row> rowData = env.createInput(inputFormat);

        //将数据map为tuple2
        DataSet<Tuple2<Integer, String>> resultSet = rowData.map(new MapFunction<Row, Tuple2<Integer, String>>() {
            @Override
            public Tuple2<Integer, String> map(Row row) throws Exception {
                return Tuple2.of((Integer) row.getField(0), row.getField(1).toString());
            }
        });

        //将数据写入MySQL
        JdbcOutputFormat jdbcOutputFormat = JdbcOutputFormat.buildJdbcOutputFormat()
                .setDrivername(props.getProperty("driver"))
                .setDBUrl(props.getProperty("url"))
                .setUsername(props.getProperty("username"))
                .setPassword(props.getProperty("password"))
                .setQuery("INSERT INTO result VALUES (?,?)") //占位符
                .setSqlTypes(new int[] {java.sql.Types.INTEGER, java.sql.Types.VARCHAR}) //设置占位符类型
                .finish();

        resultSet.addSink(new SinkFunction<Tuple2<Integer, String>>() {
            @Override
            public void invoke(Tuple2<Integer, String> value) throws Exception {
                PreparedStatement preparedStatement = jdbcOutputFormat.getPreparedStatement(value);
                preparedStatement.execute();
            }
        });

        //执行任务
        env.execute();
    }
}
```

这个示例演示了如何使用Apache Flink连接MySQL数据库并执行批处理和流处理。首先配置连接参数，然后使用JDBC输入格式读取数据。在批处理中，我们将数据映射为Tuple2并打印结果，而在流处理中，我们将数据映射为Tuple2并将其写入MySQL数据库表中。

在Flink集群中使用MyBatis Plus框架，需要将MyBatis Plus作为依赖项添加到Flink应用程序中，并集成MyBatis Plus和底层数据库的配置。这里以使用MySQL数据库为例。

首先，在Flink应用程序中添加MyBatis Plus和MySQL JDBC驱动的依赖项，例如：

```xml
<dependency>
    <groupId>com.baomidou</groupId>
    <artifactId>mybatis-plus</artifactId>
    <version>3.1.2</version>
</dependency>

<dependency>
    <groupId>mysql</groupId>
    <artifactId>mysql-connector-java</artifactId>
    <version>8.0.26</version>
</dependency>
```

然后，在应用程序中创建一个DataSource对象，它可以用于MyBatis Plus的持久化操作。在Flink集群中，通常使用Apache Flink的Hadoop FileSystem接口存储JDBC驱动和DataSource配置文件，并将它们提供给应用程序。

在作业中，可以使用以下方法获得Hadoop FileSystem：

```java
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.core.fs.Path;
import org.apache.flink.runtime.fs.hdfs.HadoopFileSystem;
import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.FileSystem;

private static final String HADOOP_CONF_PATH = "hdfs://localhost:9000/flink/hadoop/conf/core-site.xml";

public static FileSystem getFS() throws IOException {
    Configuration hadoopConf = new Configuration();
    FileSystem hdfs = FileSystem.get(new java.net.URI(HADOOP_CONF_PATH), hadoopConf);
    return new HadoopFileSystem(hdfs, new Path("/flink/jdbc"));
}
```

接下来，可以在作业中使用如下方式创建一个DataSource：

```java
import com.baomidou.mybatisplus.core.MybatisConfiguration;
import com.baomidou.mybatisplus.core.MybatisSqlSessionFactoryBuilder;
import com.baomidou.mybatisplus.core.config.GlobalConfig;
import com.baomidou.mybatisplus.extension.spring.MybatisSqlSessionFactoryBean;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.source.RichSourceFunction;
import org.apache.ibatis.session.SqlSessionFactory;

import javax.sql.DataSource;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Properties;

public class MyBatisPlusDataSource extends RichSourceFunction<DataSource> {

    private static final String MYBATIS_CONFIG_PATH = "/flink/jdbc/mybatis.xml";
    private static final String JDBC_CONFIG_PATH = "/flink/jdbc/jdbc.properties";
    private DataSource dataSource;

    @Override
    public void open(Configuration parameters) throws Exception {
        super.open(parameters);

        // 读取MyBatis配置文件
        byte[] bytes = Files.readAllBytes(Paths.get(MYBATIS_CONFIG_PATH));
        String xml = new String(bytes, StandardCharsets.UTF_8);
        MybatisSqlSessionFactoryBean builder = new MybatisSqlSessionFactoryBean();
        builder.setDataSource(dataSource);
        builder.setConfiguration(new MybatisConfiguration());
        builder.setTypeAliasesPackage("com.xyz.entity");
        builder.setMapperLocations(new PathMatchingResourcePatternResolver().getResources("classpath*:mapper/*.xml"));
        builder.setGlobalConfig(new GlobalConfig()); //如果需要逻辑删除、分页等功能需要设置分页插件和逻辑删除插件等信息
        builder.setSqlSessionFactoryBuilder(new MybatisSqlSessionFactoryBuilder());
        builder.setConfigLocation(new ByteArrayResource(xml.getBytes(StandardCharsets.UTF_8)));
        SqlSessionFactory factory = builder.getObject();

        // 读取JDBC配置文件
        Properties properties = new Properties();
        FileSystem fs = getFS();
        Path path = new Path(JDBC_CONFIG_PATH);
        if (fs.exists(path)) {
            try (FSDataInputStream in = fs.open(path)) {
                properties.load(in);
            }
        }

        // 创建DataSource
        HikariDataSource dataSource = new HikariDataSource();
        dataSource.setDriverClassName("com.mysql.cj.jdbc.Driver");
        dataSource.setJdbcUrl(properties.getProperty("url"));
        dataSource.setUsername(properties.getProperty("username"));
        dataSource.setPassword(properties.getProperty("password"));

        this.dataSource = dataSource;
    }

    @Override
    public void run(SourceContext<DataSource> sourceContext) throws Exception {
        sourceContext.collect(dataSource);
    }

    @Override
    public void cancel() {
        // no-op
    }
}
```

在这个类中，我们使用了读取Hadoop FileSystem的方法，并用于MyBatis和DataSource的配置。MyBatis的配置文件存储在`/flink/jdbc/mybatis.xml`中，JDBC配置存储在`/flink/jdbc/jdbc.properties`中。

