        switch (operation) {
            case UPDATE:
                mapper.update(new UpdateWrapper<>(value));
                break;
            case UPDATE_CHAIN:
                mapper.update(new UpdateChainWrapper<>(value));
                break;
            case DELETE:
                mapper.delete(new QueryWrapper<>(value));
                break;
            case RETRACT:
                mapper.insertOrUpdate(value);
                break;
        }
    }
