You can create a UMG Widget using the `StaticClass()` function in C++ by following these steps:

1. First, include the required headers:

```cpp
#include "Blueprint/UserWidget.h"
#include "Runtime/UMG/Public/UMG.h"
```

2. Then, load your UMG widget into a `UClass` by using the `ConstructorHelpers::FClassFinder`:

```cpp
ConstructorHelpers::FClassFinder<UUserWidget> WidgetFinder(TEXT("/Game/YOUR_WIDGET_PATH/YourWidget_BP"));
UClass* WidgetClass = nullptr;

if (WidgetFinder.Succeeded())
{
    WidgetClass = WidgetFinder.Class;
}
```

Replace `YOUR_WIDGET_PATH` and `YourWidget_BP` with the correct path and blueprint class name for your widget.

3. Next, check if the widget class is valid, create the widget, and add it to the viewport:

```cpp
if (WidgetClass != nullptr)
{
    UUserWidget* WidgetInstance = CreateWidget<UUserWidget>(GetWorld(), WidgetClass);

    if (WidgetInstance)
    {
        WidgetInstance->AddToViewport();
    }
}
```

This code will create and display an instance of your UMG widget on the screen without requiring a `TSubclassOf<UUserWidget>`. However, using the `StaticClass()` function is not the recommended way to create widgets, because it is not as efficient or as flexible as using `TSubclassOf<UUserWidget>`. Using `ConstructorHelpers::FClassFinder` to find the widget's class during runtime may also have repercussions on performance, especially if done frequently. It is generally better to use the `TSubclassOf<UUserWidget>` approach, even if it may seem cumbersome.

Since Unreal Engine 5 currently does not have specific support for Paper2D, I'll provide you with a code solution that will work with standard Paper2D characters in Unreal Engine 4, which should also be applicable to UE5.

To display a text widget above a Paper2D character's head, follow these steps:

1. Create a UMG widget that contains a `TextBlock` element that you want to display above the character's head. Let's call this widget `W_TextAboveHead`.

2. In your Paper2D character's header (`.h`) file, add the following includes:

```cpp
#include "Blueprint/UserWidget.h"
#include "Components/WidgetComponent.h"
```

3. In the character's header (`.h`) file, add the following variables:

```cpp
UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "UI")
TSubclassOf<UUserWidget> TextAboveHeadWidgetClass;

UPROPERTY(BlueprintReadWrite, VisibleAnywhere, Category = "UI")
UWidgetComponent* TextAboveHeadWidgetComponent;
```

4. In your Paper2D character's source (`.cpp`) file, initialize the TextAboveHeadWidgetComponent in the constructor:

```cpp
ATrackedCharacter() // Your custom constructor name could be different
{
    // ...

    TextAboveHeadWidgetComponent = CreateDefaultSubobject<UWidgetComponent>(TEXT("TextAboveHeadWidgetComponent"));
    TextAboveHeadWidgetComponent->SetupAttachment(RootComponent);
}
```

5. In your character's BeginPlay override function, create and attach the widget to your character:

```cpp
void ATrackedCharacter::BeginPlay()
{
    Super::BeginPlay();

    if (TextAboveHeadWidgetClass)
    {
        TextAboveHeadWidgetComponent->SetWidgetClass(TextAboveHeadWidgetClass);
        TextAboveHeadWidgetComponent->SetRelativeLocation(FVector(0.f, 0.f, CharacterHeight)); // Set the Z value to the desired height above the character's head
        TextAboveHeadWidgetComponent->SetDrawSize(FVector2D(200.f, 50.f)); // Set the width and height of your widget, adjust it to your desired size
        TextAboveHeadWidgetComponent->SetWidgetSpace(EWidgetSpace::Screen);
    }
}
```

Replace `CharacterHeight` with the desired height above the character's head where you want the widget to appear.

6. In Blueprints or C++, you can then access the TextAboveHeadWidgetComponent and set the text of your TextBlock element to display the desired text.

Remember that this code is intended for Unreal Engine 4. If you are working in Unreal Engine 5, it's highly recommended to use the native Sprite and UI components, which may have different APIs than Paper2D. The general method for displaying a text widget above a character's head remains the same, but specific class names and functions may be different in UE5.

Here is a sample code in C++ to scale a bitmap and display using layered window and GDI StretchBlt:

```C++
#include <Windows.h>

// Function to load a bitmap from file
HBITMAP LoadBitmapFromFile(LPCWSTR szFilename)
{
    HBITMAP hBitmap = NULL;
    HINSTANCE hInstance = GetModuleHandle(NULL);   // uses current executable's module handle
    HRSRC hRes = FindResource(hInstance, szFilename, RT_BITMAP);
    if (hRes != NULL)
    {
        HGLOBAL hGlobal = LoadResource(hInstance, hRes);
        void* pData = LockResource(hGlobal);
        hBitmap = CreateBitmapFromMemory(pData, dwSize);   // function to create bitmap from memory
        FreeResource(hGlobal);
    }
    return hBitmap;
}

// Function to create a bitmap from memory
HBITMAP CreateBitmapFromMemory(LPVOID pData, DWORD dwSize)
{
    HBITMAP hBitmap = NULL;
    LPBITMAPINFO pBitmapInfo = (LPBITMAPINFO)pData;
    LPVOID pBitmapData = (LPVOID)((LPBYTE)pData + pBitmapInfo->bmiHeader.biSize);
    HDC hDC = GetDC(NULL);
    hBitmap = CreateDIBitmap(hDC, &pBitmapInfo->bmiHeader, CBM_INIT, pBitmapData, pBitmapInfo, DIB_RGB_COLORS);
    ReleaseDC(NULL, hDC);
    return hBitmap;
}

// Function to display a bitmap with scaling using layered window
void DisplayScaledBitmap(HWND hWnd, HBITMAP hBitmap, int xDest, int yDest, int nDestWidth,
    int nDestHeight, int nSrcX, int nSrcY, int nSrcWidth, int nSrcHeight)
{
    HDC hSrcDC = CreateCompatibleDC(NULL);
    HDC hDestDC = GetDC(hWnd);
    HBITMAP hOldSrcBitmap = (HBITMAP)SelectObject(hSrcDC, hBitmap);

    // Create a DIB section for scaled bitmap
    BITMAPINFO bitmapInfo;
    memset(&bitmapInfo, 0, sizeof(BITMAPINFO));
    bitmapInfo.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bitmapInfo.bmiHeader.biWidth = nDestWidth;
    bitmapInfo.bmiHeader.biHeight = -nDestHeight;   // negative height to indicate a top-down bitmap
    bitmapInfo.bmiHeader.biPlanes = 1;
    bitmapInfo.bmiHeader.biBitCount = 32;
    bitmapInfo.bmiHeader.biCompression = BI_RGB;
    bitmapInfo.bmiHeader.biSizeImage = 0;
    LPDWORD pDestPixels = NULL;   // pointer to destination buffer
    HBITMAP hDestBitmap = CreateDIBSection(hDestDC, &bitmapInfo, DIB_RGB_COLORS, (LPVOID*)&pDestPixels, NULL, 0);

    // Stretch the bitmap to the scaled size with antialiasing
    SetStretchBltMode(hDestDC, HALFTONE);
    StretchBlt(hDestDC, xDest, yDest, nDestWidth, nDestHeight, hSrcDC, nSrcX, nSrcY, nSrcWidth, nSrcHeight, SRCCOPY);

    // Prepare an alpha channel mask using the transparent color (pink in this case)
    const COLORREF TRANSPARENT_COLOR = RGB(255, 0, 255);
    int nPixels = nDestWidth * nDestHeight;
    for (int i = 0; i < nPixels; i++)
    {
        COLORREF color = pDestPixels[i];
        if (color == TRANSPARENT_COLOR)
            pDestPixels[i] = 0;   // fully transparent
        else
            pDestPixels[i] |= 0xFF000000;   // opaque alpha channel
    }

    // Create a memory DC and select the destination bitmap
    HDC hMemDC = CreateCompatibleDC(hDestDC);
    HBITMAP hOldDestBitmap = (HBITMAP)SelectObject(hMemDC, hDestBitmap);

    // Set the window blend style and alpha value
    BLENDFUNCTION blend = { AC_SRC_OVER, 0, 255, AC_SRC_ALPHA };
    POINT ptDest = { xDest, yDest };   // destination point for the layered window
    SIZE sizeDest = { nDestWidth, nDestHeight };   // destination size for the layered window

    // Set the layered window attributes
    SetWindowLong(hWnd, GWL_EXSTYLE, WS_EX_LAYERED);   // set WS_EX_LAYERED style
    SetLayeredWindowAttributes(hWnd, TRANSPARENT_COLOR, 255, LWA_COLORKEY | LWA_ALPHA);   // set color key and alpha value
    UpdateLayeredWindow(hWnd, hDestDC, &ptDest, &sizeDest, hMemDC, &ptDest, 0, &blend, ULW_ALPHA);

    // Clean up
    SelectObject(hSrcDC, hOldSrcBitmap);
    DeleteDC(hSrcDC);
    SelectObject(hMemDC, hOldDestBitmap);
    DeleteDC(hMemDC);
    ReleaseDC(hWnd, hDestDC);
    DeleteObject(hDestBitmap);
}

// Sample usage
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd)
{
    // Load a bitmap file
    HBITMAP hBitmap = LoadBitmapFromFile(L"mybitmap.bmp");

    // Display the bitmap using layered window with scaling
    HWND hWnd = CreateWindow(L"MyWindowClass", L"My Window", WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, NULL, NULL, hInstance, NULL);
    DisplayScaledBitmap(hWnd, hBitmap, 0, 0, 200, 100, 0, 0, 100, 50);   // scale to 200x100 and display at (0,0)
    ShowWindow(hWnd, nShowCmd);

    // Run the message loop
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Clean up
    DeleteObject(hBitmap);
    return 0;
}
```

This code loads a bitmap from a file, scales it to a destination size using GDI StretchBlt with antialiasing, prepares an alpha channel mask using a transparent color (pink in this case), and displays the scaled bitmap using a layered window with the mask as the alpha channel. The code also sets the color key and alpha value of the layered window for transparency. The sample usage creates a window and displays the bitmap at a scaled size of 200x100 with a top-left position of (0,0).

