```c
#include <stdio.h>

// Fonction pour afficher le contenu des trois tableaux
void afficherTableaux(char poste[], int nbCafe[], int age[], int taille) {
    printf("Poste   NbCafe   Age\n");
    for (int i = 0; i < taille; i++) {
        printf("  %c        %d       %d\n", poste[i], nbCafe[i], age[i]);
    }
}

// Fonction pour compter les employés par poste
int compterPoste(char poste[], int taille, char role) {
    int count = 0;
    for (int i = 0; i < taille; i++) {
        if (poste[i] == role)
            count++;
    }
    return count;
}

// Fonction pour compter les employés selon certains critères
int compterCriteres(int tableau[], int taille, int seuil) {
    int count = 0;
    for (int i = 0; i < taille; i++) {
        if (tableau[i] >= seuil)
            count++;
    }
    return count;
}

// Fonction pour trouver la valeur maximale dans un tableau
int maxValue(int tableau[], int taille) {
    int max = tableau[0];
    for (int i = 1; i < taille; i++) {
        if (tableau[i] > max)
            max = tableau[i];
    }
    return max;
}

// Fonction pour trier les trois tableaux selon les âges
void triSelonAge(char poste[], int nbCafe[], int age[], int taille) {
    for (int i = 0; i < taille - 1; i++) {
        for (int j = i + 1; j < taille; j++) {
            if (age[i] > age[j]) {
                int tempAge = age[i];
                age[i] = age[j];
                age[j] = tempAge;

                int tempCafe = nbCafe[i];
                nbCafe[i] = nbCafe[j];
                nbCafe[j] = tempCafe;

                char tempPoste = poste[i];
                poste[i] = poste[j];
                poste[j] = tempPoste;
            }
        }
    }
}

int main() {
    char poste[] = {'P', 'P', 'O', 'A', 'P', 'A', 'P', 'P'};
    int nbCafe[] = {3, 1, 5, 0, 3, 4, 0, 3};
    int age[] = {25, 19, 27, 30, 65, 24, 56, 29};
    int taille = sizeof(poste) / sizeof(poste[0]);

