    printf("Âge maximal : %d\n", maxValue(age, taille));

    triSelonAge(poste, nbCafe, age, taille);

    printf("\nTableaux triés selon l'âge :\n");
    afficherTableaux(poste, nbCafe, age, taille);

    return 0;
}
