Unity Editor中可以使用PropertyDrawer来实现自定义数据类型的绘制和编辑。下面是一个例子，展示如何绘制一个对象数组列表：

```csharp
using UnityEngine;
using UnityEditor;

[CustomPropertyDrawer(typeof(MyClass[]))]
public class MyClassArrayDrawer : PropertyDrawer
{
    public override void OnGUI(Rect position, SerializedProperty property, GUIContent label)
    {
        EditorGUI.BeginProperty(position, label, property);

        // Show label
        position = EditorGUI.PrefixLabel(position, GUIUtility.GetControlID(FocusType.Passive), label);

        // Calculate single element height
        var height = EditorGUIUtility.singleLineHeight + EditorGUIUtility.standardVerticalSpacing;

        // Draw list of elements
        var arraySize = property.arraySize;
        var elementPosition = position;
        for (int i = 0; i < arraySize; i++)
        {
            // Calculate element position and size
            elementPosition.height = EditorGUI.GetPropertyHeight(property.GetArrayElementAtIndex(i), GUIContent.none, true);
            elementPosition.y += height;

            // Draw element property
            EditorGUI.PropertyField(elementPosition, property.GetArrayElementAtIndex(i), GUIContent.none, true);
        }

        // Add button to add elements
        var addButtonPosition = position;
        addButtonPosition.y += height * (arraySize + 1);
        addButtonPosition.height = EditorGUIUtility.singleLineHeight;
        if (GUI.Button(addButtonPosition, "Add Element"))
        {
            property.InsertArrayElementAtIndex(arraySize);
        }

        EditorGUI.EndProperty();
    }

    public override float GetPropertyHeight(SerializedProperty property, GUIContent label)
    {
        var height = EditorGUIUtility.singleLineHeight + EditorGUIUtility.standardVerticalSpacing;

        var arraySize = property.arraySize;
        for (int i = 0; i < arraySize; i++)
        {
            height += EditorGUI.GetPropertyHeight(property.GetArrayElementAtIndex(i), GUIContent.none, true) + EditorGUIUtility.standardVerticalSpacing;
        }

        return height + EditorGUIUtility.singleLineHeight;
    }
}
```

