            Mono<Map<String, String>> tagsMono = Mono.fromCallable(() -> {
                Map<String, String> tags = new HashMap<>();
                tags.put(blobSourceConfiguration.getTagKey(), blobSourceConfiguration.getReadTagValue());
                return tags;
            }).subscribeOn(Schedulers.boundedElastic());

            Mono<Void> setTagsMono = Mono.zip(clientMono, tagsMono)
                    .flatMap(tuple -> tuple.getT1().setTags(tuple.getT2()))
                    .then();

            Mono<byte[]> downloadContentMono = Mono.fromCallable(() -> blobClient.downloadContent().toBytes())
                    .subscribeOn(Schedulers.boundedElastic());

            return Mono.zip(setTagsMono, downloadContentMono)
                    .then(Mono.just(blobItem.getName()));
        })
        .publishOn(Schedulers.boundedElastic())
    );

