            _violationMidlHealthDamage.SendViolationVehicleCollision();
        }
        else
        {
            _violationHardHealthDamage.SendViolationVehicleCollision();
        }
    }

    // Handle collision with other objects
    private void HandleObjectCollision()
    {
        _violationCollisionObject.SendViolationVehicleCollision();
    }
}
