    const int numPoints = static_cast<int>((m_freqMax - m_freqMin) / m_sampleRate) + 1;
    std::vector<double> spectrum(numPoints, 0.0);

    for (const SignalInfo& info : m_signals) {
        for (int i = 0; i < numPoints; ++i) {
            double freq = i * m_sampleRate - info.carrierFrequency;

            double signalSpectrum = 0.0;

            if (info.modulation == SignalInfo::Modulation::AM) {
