        std::normal_distribution<double> dist(0.0, 1.0); // Mean = 0, standard deviation = 1

        for (size_t i = 0; i < complex_spectrum.size(); ++i) {
            double noise_re = dist(gen) / std::sqrt(2 * snr_);
            double noise_im = dist(gen) / std::sqrt(2 * snr_);
            complex_spectrum[i] += std::complex<double>(noise_re, noise_im);
        }
    }

