    std::vector<double> createPowerSpectrum(const std::vector<std::complex<double>>& complex_spectrum) {
        std::vector<double> power_spectrum(complex_spectrum.size());

        for (size_t i = 0; i < complex_spectrum.size(); ++i) {
            power_spectrum[i] = 10.0 * std::log10(std::norm(complex_spectrum[i]));
