          sampleRate_(sampleRate),
          noiseFloor_(noiseFloor),
          snr_(snr),
          noiseSpectrum_(generateNoise()) {}

    Spectrum generateSpectrum(const std::vector<Signal> &signals) {
        Spectrum result = noiseSpectrum_;
        for (const Signal &signal : signals) {
            Spectrum signalSpectrum = generateSignalSpectrum(signal);
            addSpectrum(result, signalSpectrum);
        }
        return result;
    }

private:
    double startFrequency_;
    double endFrequency_;
    double sampleRate_;
    double noiseFloor_;
    double snr_;
    Spectrum noiseSpectrum_;

    Spectrum generateNoise() {
        std::size_t points = std::ceil((endFrequency_-startFrequency_) * sampleRate_);
        Spectrum noise(points);

        std::random_device rd;
        std::default_random_engine eng(rd());
        std::normal_distribution<double> noiseDist(0.0, pow(10,(noiseFloor_/10.0)));

        for(double& point : noise){
            point = noiseDist(eng);
        }
        return noise;
    }

    Spectrum generateSignalSpectrum(const Signal &signal) {
        std::size_t points = std::ceil((signal.bandwidth) * sampleRate_);

        std::vector<std::complex<double>> complexSpectrum(points);

        double timeStep = 1.0 / sampleRate_;
        double omega = 2 * M_PI * signal.frequency;

        for (std::size_t i = 0; i < points; ++i) {
            double t = i * timeStep;
            double am = pow(10,(signal.power/20.0)) * cos(omega * t);
            complexSpectrum[i] = std::complex<double>(am, 0.0);
        }

        fft(complexSpectrum);
        powerSpectrum(complexSpectrum);

        Spectrum result(points);
        for (std::size_t i = 0; i < points; ++i) {
            result[i] = 10.0 * log10(complexSpectrum[i].real());
        }

        return result;
    }

    void addSpectrum(Spectrum &a, const Spectrum &b) {
        if(a.size()!= b.size()){
            throw std::runtime_error("Mismatched spectrum size");
        }
        for(std::size_t i =0; i<a.size(); ++i){
            a[i] += b[i];
        }
    }

    void fft(std::vector<std::complex<double>> &x) {
        // Implement the Cooley-Tukey FFT algorithm here
    }

    void powerSpectrum(std::vector<std::complex<double>> &spectrum) {
        for (std::complex<double> &val : spectrum) {
            val = std::norm(val);
        }
    }
};

