}
public static void mixAudioFiles(File inputFile1, File inputFile2, File outputFile, float volumePercent1, float volumePercent2) {
    try {
        validateVolumePercent(volumePercent1);
        validateVolumePercent(volumePercent2);
        if (!inputFile1.exists() || !inputFile1.canRead() || !inputFile2.exists() || !inputFile2.canRead()) {
            throw new IOException("Input files must exist and be readable.");
        }
        float[] samples1 = readSamples(inputFile1);
        float[] samples2 = readSamples(inputFile2);
        if (samples1 == null || samples2 == null) {
            return;
        }
        float[] mixedSamples = mixSamples(samples1, samples2, volumePercent1, volumePercent2);
        if (!writeSamplesToFile(mixedSamples, outputFile)) {
            return;
        }
        if (!encodeAudioFile(outputFile, new File(outputFile.getPath() + ".mp3"))) {
            return;
        }
    } catch (IOException ex) {
        ex.printStackTrace();
    }
}
private static void validateVolumePercent(float volumePercent) {
    if (volumePercent < 0 || volumePercent > 100) {
        throw new IllegalArgumentException("Volume percentage must be between 0 and 100.");
    }
}
private static boolean encodeAudioFile(File inputFile, File outputFile) {
    try {
        List<String> command = new ArrayList<>();
        command.add("ffmpeg");
        command.add("-i");
        command.add(inputFile.getAbsolutePath());
        command.add("-vn");
        command.add("-codec:a");
        command.add("libmp3lame");
        command.add("-qscale:a");
        command.add("2");
        command.add(outputFile.getAbsolutePath());
        ProcessBuilder processBuilder = new ProcessBuilder(command)
                .redirectError(ProcessBuilder.Redirect.INHERIT)
                .redirectOutput(ProcessBuilder.Redirect.PIPE);
        Process process = processBuilder.start();
        int exitCode = process.waitFor();
        return exitCode == 0;
    } catch (IOException ex) {
        ex.printStackTrace();
        return false;
    } catch (InterruptedException ex) {
        Thread.currentThread().interrupt();
        ex.printStackTrace();
        return false;
    }
}
private static boolean isFfmpegInstalled() {
    try {
        ProcessBuilder pb = new ProcessBuilder("ffmpeg", "-version");
        pb.redirectError(ProcessBuilder.Redirect.INHERIT);
        Process p = pb.start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
