        return false;
    }
}
private static boolean writeSamplesToFile(float[] samples, File outputFile) throws IOException {
    String ffmpegCommand = "ffmpeg -y -f s16le -ar 44100 -ac 1 -i pipe:0 -acodec pcm_s16le -f mp3 " + outputFile.getAbsolutePath();
    List<String> command = Arrays.asList(ffmpegCommand.split(" "));
    if (!isFfmpegInstalled()) {
        return false;
    }
    ProcessBuilder processBuilder = new ProcessBuilder(command);
    Process process = null;
    OutputStream outputStream = null;
    try {
