            buffer.flip();
            outputStream.write(buffer.array());
            buffer.clear();
        }
        outputStream.flush();
        outputStream.close();
        int exitCode = process.waitFor();
        return exitCode == 0;
    } catch (IOException | InterruptedException e) {
        e.printStackTrace();
        return false;
    } finally {
        if (outputStream != null) {
            outputStream.close();
        }
        if (process != null) {
            process.destroy();
        }
    }
