        String ffmpegCommand = "ffmpeg -i " + audioFile.getAbsolutePath() + " -f s16le -acodec pcm_s16le " + tempFile.toAbsolutePath();
        List<String> command = Arrays.asList(ffmpegCommand.split(" "));
        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectError(ProcessBuilder.Redirect.INHERIT);
        Process process = null;
        SeekableByteChannel channel = null;
        try {
            process = processBuilder.start();
            channel = Files.newByteChannel(tempFile);
            ByteBuffer buffer = ByteBuffer.allocate(4096);
            List<Float> samplesList = new ArrayList<>();
            while (channel.read(buffer) > 0) {
                buffer.flip();
                while (buffer.remaining() >= 2) {
                    short sample = buffer.getShort();
                    float normalized = sample / 32768f;
                    samplesList.add(normalized);
                }
                buffer.compact();
            }
            if (samplesList.isEmpty()) {
                return null;
            }
            float[] samples = new float[samplesList.size()];
            for (int i = 0; i < samplesList.size(); i++) {
                samples[i] = samplesList.get(i);
            }
            return samples;
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        } finally {
            if (channel != null) {
                channel.close();
            }
            if (process != null) {
                process.destroy();
            }
        }
    } finally {
        Files.deleteIfExists(tempFile);
    }
}
private static float[] mixSamples(float[] samples1, float[] samples2, float volumePercent1, float volumePercent2) {
    int maxSampleLength = Math.max(samples1.length, samples2.length);
    float[] mixedSamples = new float[maxSampleLength];
    for (int i = 0; i < maxSampleLength; i++) {
        float sample1 = i < samples1.length ? samples1[i] : 0;
        float sample2 = i < samples2.length ? samples2[i] : 0;
        mixedSamples[i] = (sample1 * volumePercent1 / 100f) + (sample2 * volumePercent2 / 100f);
    }
    return mixedSamples;
}
