document.addEventListener("keydown", event => {
    keys[event.code] = true;
});
document.addEventListener("keyup", event => {
    keys[event.code] = false;
});

function updatePlayerVelocity() {
    if (keys["ArrowLeft"] || keys["KeyA"]) {
        player.velocityX = -4;
    } else if (keys["ArrowRight"] || keys["KeyD"]) {
        player.velocityX = 4;
    } else {
        player.velocityX = 0;
    }
}

function update() {
    updatePlayerVelocity();

    // Update player positions
    player.x += player.velocityX;
    player.y += player.velocityY;

    clearCanvas();
    draw();
}
```

5. Next, add gravity and collision detection for the player with platforms. Add the following code to `platformer.js`:

```javascript
const gravity = 1;
const groundFriction = 0.8;

function applyGravity() {
    player.velocityY += gravity;
}

function checkPlatformCollision() {
    platforms.forEach(platform => {
        if (
            player.x < platform.x + platform.width &&
            player.x + player.width > platform.x &&
            player.y < platform.y + platform.height &&
            player.y + player.height > platform.y
        ) {
            // Colliding with platform
            player.y = platform.y - player.height;
            player.velocityY = 0;
        }
    });
}

function applyGroundFriction() {
    if (player.velocityY === 0) {
        player.velocityX *= groundFriction;
    }
}

function update() {
    updatePlayerVelocity();

    // Apply gravity and friction
    applyGravity();
    applyGroundFriction();

    // Update player positions
    player.x += player.velocityX;
    player.y += player.velocityY;

    // Check for collisions
    checkPlatformCollision();

    clearCanvas();
    draw();
}
```

This code adds a basic gravity effect and ground friction, as well as collision detection with platforms. You can further evolve this code by adding jumping controls, more platforms, and better collision detection.

