### Step 4: Implement the language learning app functionality

Now you'll need to create the JavaScript code to handle the language-learning interactions. Edit the `js/main.js` file and start by adding some sample data and basic functions:

```javascript
const lessons = [
    {
        question: "Translate: Cat",
        answers: ["Gato", "Perro", "Pájaro", "Pez"],
        correctAnswer: "Gato"
    },
    {
        question: "Translate: Dog",
        answers: ["Gato", "Perro", "Pájaro", "Pez"],
        correctAnswer: "Perro"
    },
    // Add more lessons here
];

function createQuestionElement(lesson) {
    // Create a div for the question element
    const questionDiv = document.createElement('div');
    questionDiv.classList.add('question');

    // Add question text
    const questionText = document.createElement('p');
    questionText.textContent = lesson.question;
    questionDiv.appendChild(questionText);

    // Add answers
    for (const answer of lesson.answers) {
        const answerButton = document.createElement('button');
        answerButton.textContent = answer;
        answerButton.addEventListener('click', () => checkAnswer(lesson, answer));
        questionDiv.appendChild(answerButton);
    }

    return questionDiv;
}

function checkAnswer(lesson, answer) {
    if (lesson.correctAnswer === answer) {
        // Correct answer
        alert('Correct!');
    } else {
        // Incorrect answer
        alert('Incorrect. Try again.');
    }
}

function displayLesson(lesson) {
    const questionElement = createQuestionElement(lesson);
    document.querySelector('main').appendChild(questionElement);
}
```

Now you can display a random lesson on the page by modifying the `main.js` file:

```javascript
function getRandomLesson() {
    const randomIndex = Math.floor(Math.random() * lessons.length);
    return lessons[randomIndex];
}

// Display a random lesson when the page loads
displayLesson(getRandomLesson());
```

