    // Add this block to manage quiver spawn and behavior
    if (Math.random() < 0.5 && (Date.now() - this.lastQuiverSpawnTime >= 1500 || !this.quiver)) {
      this.quiver = new Quiver(alea(this.canvas.width - Quiver.QUIVER_WIDTH), Quiver.randomYPosition())
      this.lastQuiverSpawnTime = Date.now()
    }
    if (this.quiver) {
      this.quiver.move(this.canvas)
