To display the "soreness_label" value of the latest data, you need to adapt your ValueEventListener. To do that, you can sort the Firebase Realtime Database by the "timestamp" and limit the query to the last record using `orderByChild("timestamp")` and `limitToLast(1)`.

Here's the modified code for `TextResult.java`:

```java
package com.example.profile;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import android.os.Bundle;
import android.util.Log;
import android.widget.TextView;
import com.google.firebase.database.DataSnapshot;
import com.google.firebase.database.DatabaseError;
import com.google.firebase.database.DatabaseReference;
import com.google.firebase.database.FirebaseDatabase;
import com.google.firebase.database.Query;
import com.google.firebase.database.ValueEventListener;

public class TextResult extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        FirebaseDatabase database = FirebaseDatabase.getInstance();
        DatabaseReference myRef = database.getReference();
        Query query = myRef.orderByChild("timestamp").limitToLast(1);
        query.addValueEventListener(new ValueEventListener() {
            @Override
            public void onDataChange(@NonNull DataSnapshot dataSnapshot) {
                // dataSnapshot contains the latest entry as a whole
                for (DataSnapshot snapshot : dataSnapshot.getChildren()) {
                    // Get the "soreness_label" from latest entry
                    String latestSorenessLabel = snapshot.child("soreness_label").getValue(String.class);

                    // Display it in the text view
                    TextView textViewData = findViewById(R.id.textViewData);
                    textViewData.setText(latestSorenessLabel);
                }
            }

            @Override
            public void onCancelled(@NonNull DatabaseError databaseError) {
                // Handle any errors
                Log.w("Error", "Failed to read value.", databaseError.toException());
            }
        });

    }

}
```

This code will now display the latest "soreness_label" in the TextView. Make sure to replace the reference to the Firebase Realtime Database with the correct path, if necessary.

