using System.Net;
using SharpAdbClient;

public class AdbHelper
{
    public static void DialCode(string code)
    {
        try
        {
            // Locate the connected Android device
            var devices = AdbClient.Instance.GetDevices();
            var device = devices.FirstOrDefault();

            if (device == null)
            {
                Console.WriteLine("No connected device found.");
                return;
            }

            // Open a shell on the Android device
            using (var socket = new AdbSocket(new IPEndPoint(IPAddress.Loopback, AdbClient.AdbServerPort)))
            {
                var receiver = new ConsoleOutputReceiver();
                AdbClient.Instance.ExecuteRemoteCommand($"am broadcast -a android.intent.action.CALL tel:{code}", device, receiver);

                Console.WriteLine(receiver.ToString());
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
