You can use the following C++ program to remove the "<" and ">" characters from the filenames:

```cpp
#include <iostream>
#include <string>
#include <filesystem>
#include <algorithm>

namespace fs = std::filesystem;

std::string remove_special_chars(const std::string& filename) {
    std::string new_filename = filename;
    new_filename.erase(std::remove(new_filename.begin(), new_filename.end(), '<'), new_filename.end());
    new_filename.erase(std::remove(new_filename.begin(), new_filename.end(), '>'), new_filename.end());
    return new_filename;
}

int main() {
    std::string path = "."; // Change this with the path of your folder containing files

    try {
        for (const auto& entry : fs::directory_iterator(path)) {
            std::string old_filename = entry.path().string();
            if (entry.path().extension() == ".txt" && 
                (old_filename.find('<') != std::string::npos || 
                 old_filename.find('>') != std::string::npos)) {
                std::string new_filename = remove_special_chars(old_filename);
                fs::rename(old_filename, new_filename);
                std::cout << "Renamed " << old_filename << " to " << new_filename << std::endl;
            }
        }
    } catch (const fs::filesystem_error& e) {
        std::cerr << e.what() << std::endl;
    }

    return 0;
}
```

