Creating a complete, realistic character controller for a first-person shooter in Unity requires a lot of code and functionality. I will help get you started with a basic outline for a character controller in C# that includes the necessary features you mentioned. For more advanced features like leaning, inertia, and proper physics handling, I recommend referring to Unity tutorials and resources specifically designed for this.

Here's a sample script for a simplified character controller in C# you can use as a starting point:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class FPSCharacterController : MonoBehaviour
{
    [Header("Movement Settings")]
    public float walkSpeed = 3f;
    public float sprintSpeed = 6f;
    public float crouchSpeed = 1f;
    public float crouchHeight = 0.5f;
    public float gravity = -30f;
    public float jumpHeight = 1f;

    [Header("Look Settings")]
    public Transform cameraTransform;
    public float lookSpeedX = 2f;
    public float lookSpeedY = 2f;
    public float lookClampY = 80f;

    private CharacterController controller;
    private Vector3 velocity;
    private bool isCrouching = false;
    private float originalHeight;
    private float rotationX = 0f;

    private void Start()
    {
        controller = GetComponent<CharacterController>();
        originalHeight = controller.height;
        Cursor.lockState = CursorLockMode.Locked;
    }

    private void Update()
    {
        // Handle movement input
        float speed = isCrouching ? crouchSpeed : (Input.GetKey(KeyCode.LeftShift) ? sprintSpeed : walkSpeed);
        Vector3 move = transform.TransformDirection(new Vector3(Input.GetAxisRaw("Horizontal"), 0, Input.GetAxisRaw("Vertical")).normalized) * speed;
        controller.SimpleMove(move);

        // Crouch
        if (Input.GetKeyDown(KeyCode.LeftControl))
        {
            isCrouching = !isCrouching;
            controller.height = isCrouching ? crouchHeight : originalHeight;
            cameraTransform.localPosition = new Vector3(cameraTransform.localPosition.x, isCrouching ? crouchHeight : originalHeight, cameraTransform.localPosition.z);
        }

        // Apply gravity
        if (controller.isGrounded && velocity.y < 0) velocity.y = 0;
        velocity.y += gravity * Time.deltaTime;
        controller.Move(velocity * Time.deltaTime);

        // Jump
        if (controller.isGrounded && Input.GetButtonDown("Jump"))
        {
            velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity);
        }

        // Camera rotation
        rotationX -= Input.GetAxis("Mouse Y") * lookSpeedY;
        rotationX = Mathf.Clamp(rotationX, -lookClampY, lookClampY);

        cameraTransform.localRotation = Quaternion.Euler(rotationX, 0, 0);
        transform.rotation *= Quaternion.Euler(0, Input.GetAxis("Mouse X") * lookSpeedX, 0);
    }
}
```

This script provides basic functionality for walking, sprinting, jumping, and crouching. Keep in mind that this is a simplified character controller, and for advanced capabilities and better realism, you may need to implement additional features and optimizations. I recommend checking Unity tutorials that specifically focus on character controllers in first-person shooters.

