To create a JavaScript script that visualizes a video with an animated face, we'll use the HTML canvas element along with the `window.requestAnimationFrame` method for the animation loop. I'll use a sample video from the Wikimedia Foundation for this example.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Video Visualization with Animated Face</title>
    <style>
        canvas { display: block; margin: 0 auto; }
    </style>
</head>
<body>
    <video id="video" width="640" height="360" crossorigin="anonymous">
        <source src="https://upload.wikimedia.org/wikipedia/commons/transcoded/9/93/Sintel_movie_trailer.webm/Sintel_movie_trailer.webm.480p.vp9.webm" type="video/webm">
        Your browser does not support the video tag.
    </video>
    <canvas id="canvas"></canvas>
    <script>
        const video = document.getElementById('video');
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        let faceSize = 20;

        canvas.width = 640;
        canvas.height = 360;

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height); // Clear the canvas
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height); // Draw the video on the canvas

            faceSize += Math.random() * 2 - 1; // Add animation to the face size
            faceSize = Math.min(Math.max(faceSize, 10), 50);

            // Find the center of the canvas
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            // Draw the animated face
            drawFace(centerX, centerY);
            window.requestAnimationFrame(draw);
        }

        function drawFace(x, y) {
            // Draw the face circle
            ctx.fillStyle = 'rgba(255, 0, 0, 0.5)';
            ctx.beginPath();
            ctx.arc(x, y, faceSize, 0, Math.PI * 2);
            ctx.fill();

            // Draw the eyes
            ctx.fillStyle = 'white';
            ctx.beginPath();
            ctx.arc(x - faceSize / 2, y - faceSize / 2, faceSize / 4, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.arc(x + faceSize / 2, y - faceSize / 2, faceSize / 4, 0, Math.PI * 2);
            ctx.fill();

            // Draw the pupils
            ctx.fillStyle = 'black';
            ctx.beginPath();
            ctx.arc(x - faceSize / 2, y - faceSize / 2, faceSize / 8, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.arc(x + faceSize / 2, y - faceSize / 2, faceSize / 8, 0, Math.PI * 2);
            ctx.fill();

            // Draw the mouth
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(x, y + faceSize / 3, faceSize / 2, 0, Math.PI);
            ctx.stroke();
        }

        video.addEventListener('canplay', () => {
            video.play();
            window.requestAnimationFrame(draw);
        });

        video.addEventListener('click', () => {
            if (video.paused) {
                video.play();
            } else {
                video.pause();
            }
        });
    </script>
</body>
</html>
```

Copy and paste this HTML code into a new file, and load the file in the browser. The script will display a video on the canvas and add an animated face on top of it. The face size changes randomly to create the animation effect. When clicking on the video, it will start playing (or pause if playing).

