```java
private void setUserRoleSyncConfig(ShareUserRole userRole, WorkspaceShare currentWorkspaceShare,
                                   List<WorkspaceShare> allWorkspaceShares) {
    if (!currentWorkspaceShare.getSyncDisplayField() || currentWorkspaceShare.getRealSenderId().equals(currentWorkspaceShare.getOwnerId())) {
        userRole.setSyncWithUserId(currentWorkspaceShare.getRealSenderId());
        userRole.setSyncDisplayField(currentWorkspaceShare.getSyncDisplayField());
        return;
    }

    processShares(userRole, currentWorkspaceShare, allWorkspaceShares);
}

private void processShares(ShareUserRole userRole, WorkspaceShare currentWorkspaceShare,
                           List<WorkspaceShare> allWorkspaceShares) {
    String currentUserId = currentWorkspaceShare.getRealSenderId();
    List<String> currentUserGroupIds = identityManager.findUserGroupIdsByUserId(currentUserId);

    List<WorkspaceShare> userShares = filterSharesByUserId(allWorkspaceShares, currentWorkspaceShare, currentUserId);
    List<WorkspaceShare> userGroupShares = filterSharesByUserGroupIds(allWorkspaceShares, currentWorkspaceShare, currentUserGroupIds);

    if (currentWorkspaceShare.getShareType() == ShareType.SPACE) {
        processSpaceShares(userRole, currentWorkspaceShare, allWorkspaceShares, userShares, userGroupShares);
    } else {
        processFolderShares(userRole, currentWorkspaceShare, allWorkspaceShares, userShares, userGroupShares, currentUserId, currentUserGroupIds);
    }
}

private List<WorkspaceShare> filterSharesByUserId(List<WorkspaceShare> allWorkspaceShares, WorkspaceShare currentWorkspaceShare, String currentUserId) {
    return allWorkspaceShares.stream()
            .filter(workspaceShare -> workspaceShare.getShareId().equals(currentWorkspaceShare.getShareId())
                    && currentUserId.equals(workspaceShare.getReceiverId()))
            .collect(toList());
}

private List<WorkspaceShare> filterSharesByUserGroupIds(List<WorkspaceShare> allWorkspaceShares, WorkspaceShare currentWorkspaceShare, List<String> currentUserGroupIds) {
    return allWorkspaceShares.stream()
            .filter(workspaceShare -> workspaceShare.getShareId().equals(currentWorkspaceShare.getShareId())
                    && currentUserGroupIds.contains(workspaceShare.getReceiverId()))
            .collect(toList());
}

private void processSpaceShares(ShareUserRole userRole, WorkspaceShare currentWorkspaceShare, List<WorkspaceShare> allWorkspaceShares, List<WorkspaceShare> userShares, List<WorkspaceShare> userGroupShares) {
    processSharesByFirstResult(userRole, userShares, allWorkspaceShares);
    if (!userGroupShares.isEmpty()) {
        if (!isAllSharesSync(userGroupShares)) {
            processSharesByFirstUnsync(userRole, userGroupShares);
        } else {
            setUserRoleSyncConfig(userRole, userGroupShares.get(0), allWorkspaceShares);
        }
    } else {
        userRole.setSyncWithUserId(null);
        userRole.setSyncDisplayField(false);
    }
}

private void processFolderShares(ShareUserRole userRole, WorkspaceShare currentWorkspaceShare, List<WorkspaceShare> allWorkspaceShares, List<WorkspaceShare> userShares, List<WorkspaceShare> userGroupShares, String currentUserId, List<String> currentUserGroupIds) {
    boolean handled = processSharesByFirstResult(userRole, userShares, allWorkspaceShares);

    if (!handled) {
        List<WorkspaceShare> parentFolderShares = calculateParentFolderShares(allWorkspaceShares, currentWorkspaceShare, currentUserId, currentUserGroupIds);
        if (!parentFolderShares.isEmpty()) {
            setUserRoleSyncConfig(userRole, parentFolderShares.get(0), allWorkspaceShares);
        } else {
            processSpaceShares(userRole, currentWorkspaceShare, allWorkspaceShares, userShares, userGroupShares);
        }
    } else {
        if (!isAllSharesSync(userGroupShares)) {
            processSharesByFirstUnsync(userRole, userGroupShares);
        } else {
            setUserRoleSyncConfig(userRole, userGroupShares.get(0), allWorkspaceShares);
        }
    }
}

private boolean processSharesByFirstResult(ShareUserRole userRole, List<WorkspaceShare> workspaceShares, List<WorkspaceShare> allWorkspaceShares) {
    Optional<WorkspaceShare> workspaceShareOpt = workspaceShares.stream().findFirst();
    if (workspaceShareOpt.isPresent()) {
        setUserRoleSyncConfig(userRole, workspaceShareOpt.get(), allWorkspaceShares);
        return true;
    }
    return false;
}

private boolean isAllSharesSync(List<WorkspaceShare> workspaceShares) {
    return workspaceShares.stream().allMatch(WorkspaceShare::getSyncDisplayField);
}

private void processSharesByFirstUnsync(ShareUserRole userRole, List<WorkspaceShare> workspaceShares) {
    Optional<WorkspaceShare> workspaceShareOpt = workspaceShares.stream().filter(ws -> !ws.getSyncDisplayField()).findFirst();
    if (workspaceShareOpt.isPresent()) {
        WorkspaceShare unsyncShare = workspaceShareOpt.get();
        userRole.setSyncWithUserId(unsyncShare.getRealSenderId());
        userRole.setSyncDisplayField(unsyncShare.getSyncDisplayField());
    }
}

private List<WorkspaceShare> calculateParentFolderShares(List<WorkspaceShare> allWorkspaceShares,
        WorkspaceShare currentWorkspaceShare, String currentUserId, List<String> currentUserGroupIds) {
    List<String> allSelfAndParentFolderIds = folderManager.getAllSelfAndParentFolderIds(currentWorkspaceShare.getFolderId());
    return allWorkspaceShares.stream()
            .filter(sharedSpace -> sharedSpace.getShareType() == ShareType.FOLDER &&
                    allSelfAndParentFolderIds.contains(sharedSpace.getFolderId()) &&
                    (currentUserGroupIds.contains(sharedSpace.getReceiverId())
                            || currentUserId.equals(sharedSpace.getReceiverId())))
            .sorted(Comparator.comparingInt(o -> allSelfAndParentFolderIds.indexOf(o.getFolderId()))
                    .reversed())
            .collect(Collectors.toList());
}
