private void processShares(ShareUserRole userRole, WorkspaceShare currentWorkspaceShare,
                           List<WorkspaceShare> allWorkspaceShares) {
    String currentUserId = currentWorkspaceShare.getRealSenderId();
    String currentShareId = currentWorkspaceShare.getShareId();
    ShareType currentShareType = currentWorkspaceShare.getShareType();

    List<String> userGroupIds = identityManager.findUserGroupIdsByUserId(currentUserId);

    Predicate<WorkspaceShare> byUserId = ws -> ws.getReceiverId().equals(currentUserId);
    Predicate<WorkspaceShare> byUserGroupId = ws -> userGroupIds.contains(ws.getReceiverId());

    Optional<WorkspaceShare> userShare = allWorkspaceShares.stream()
            .filter(ws -> ws.getShareId().equals(currentShareId) && byUserId.test(ws))
            .findFirst();

    List<WorkspaceShare> userGroupShares = allWorkspaceShares.stream()
            .filter(ws -> ws.getShareId().equals(currentShareId) && byUserGroupId.test(ws))
            .collect(toList());

    if (userShare.isPresent()) {
        setUserRoleSyncConfig(userRole, userShare.get(), allWorkspaceShares);
    } else {
        processGroupShares(userRole, currentWorkspaceShare, allWorkspaceShares, userGroupShares);
    }
}

private void processGroupShares(ShareUserRole userRole, WorkspaceShare currentWorkspaceShare,
                                List<WorkspaceShare> allWorkspaceShares, List<WorkspaceShare> userGroupShares) {
    if (userGroupShares.isEmpty()) {
        userRole.setSyncWithUserId(null);
        userRole.setSyncDisplayField(false);
        return;
    }

    WorkspaceShare firstUnsyncShare = userGroupShares.stream()
            .filter(ws -> !ws.getSyncDisplayField())
            .findFirst()
            .orElse(null);

    if (firstUnsyncShare != null) {
        userRole.setSyncWithUserId(firstUnsyncShare.getRealSenderId());
        userRole.setSyncDisplayField(false);
    } else {
        setUserRoleSyncConfig(userRole, userGroupShares.get(0), allWorkspaceShares);
    }
}
