```javascript
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Game Variables
const bird = new Bird();
const pipes = [];

// Game Loop
function gameLoop() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update and draw bird
    bird.update();
    bird.draw();

    // Update and draw pipes
    updatePipes();
    drawPipes();

    // Loop the game
    requestAnimationFrame(gameLoop);
}

// Initialize the game
gameLoop();
```

3. Create the Bird class with basic movement:

```javascript
class Bird {
    constructor() {
        this.x = canvas.width / 2;
        this.y = canvas.height / 2;
        this.size = 20;
        this.speed = 0;
    }

    update() {
        this.speed += 0.5;
        this.y += this.speed;

        if (this.y + this.size > canvas.height || this.y - this.size < 0) {
            this.speed = 0;
        }
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
    }
}
```

