// ==UserScript==
// @name         Amazon Search Results Limit Increaser
// @version      1
// @description  Increase the limit of search results on Amazon pages
// @match        https://www.amazon.*
// @grant        none
// ==/UserScript==

(function() {
    'use strict';

    const maxResults = 50; // change this value to your desired limit

    if (window.location.href.includes('/s?')) {
        const resultCount = document.getElementById('s-result-count');
        if (resultCount) {
            const resultText = resultCount.innerText;
            const pageCount = resultText.match(/\d+/g)[1]; // get the number of search pages
            const newCount = maxResults * pageCount;
            const newUrl = window.location.href.replace(/&s=[\d]+/, '')
                .replace(/&rh[pn]=[\d]+/g, '')
                + `&s=1&rhpn=${maxResults}&_encoding=UTF8&sw=${maxResults}&page=1`;
            // the newUrl changes the query parameters accordingly to the limit and total result count
            window.location.href = newUrl;
        }
    }
})();
```

