First, you need to have Redis and PostgreSQL set up and configured. Then, you can start implementing the card number generation algorithm in Golang. Below is a sample implementation of the generator and storage in Redis and PostgreSQL:

1. Install required packages:

```sh
$ go get -u github.com/go-redis/redis/v8 github.com/lib/pq
```

2. Create a file `main.go`:

```go
package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"math/rand"
	"strconv"
	"sync"
	"time"

	"github.com/go-redis/redis/v8"
	_ "github.com/lib/pq"
)

type CardGenerator struct {
	db    *sql.DB
	redis *redis.Client
}

func main() {
	err := run()
	if err != nil {
		fmt.Printf("Error running CardGenerator: %v\n", err)
	}
}

func run() error {
	db, err := setupDatabase()
	if err != nil {
		return err
	}

	redisClient := setupRedis()

	cardGenerator := &CardGenerator{
		db:    db,
		redis: redisClient,
	}

	iin := "123456"
	n := 2 // Number of cards to generate

	for i := 0; i < n; i++ {
		ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)
		defer cancel()

		cardNumber, err := cardGenerator.GenerateCardNumber(ctx, iin)
		if err != nil {
			return err
		}

		fmt.Printf("Generated Card Number: %s\n", cardNumber)
	}

	return nil
}

func setupDatabase() (*sql.DB, error) {
	connStr := "dbname=sample-db user=postgres password=secret host=127.0.0.1 port=5432 sslmode=disable"
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		return nil, err
	}

	return db, nil
}

func setupRedis() *redis.Client {
	return redis.NewClient(&redis.Options{
		Addr:     "localhost:6379",
		Password: "",
		DB:       0,
	})
}

func (cg *CardGenerator) GenerateCardNumber(ctx context.Context, iin string) (string, error) {
	mutex := cg.redis.Lock(ctx, "card_lock")
	defer mutex.Unlock(ctx)

	for i := 0; i < 10; i++ {
		cardNumber := generateRandomCardNumber(iin, 16, 19)
		exists, err := cg.checkIfExists(ctx, cardNumber)
		if err != nil {
			return "", err
		}

		if !exists {
			err = cg.storeCardNumber(ctx, iin, cardNumber)
			if err != nil {
				return "", err
			}
			return cardNumber, nil
		}
	}

	return "", errors.New("No card numbers left to generate for the given BIN")
}

func (cg *CardGenerator) checkIfExists(ctx context.Context, cardNumber string) (bool, error) {
	// Check if card exists
	err := cg.redis.Get(ctx, "card:"+cardNumber).Err()
	if err == redis.Nil {
		return false, nil
	} else if err != nil {
		return false, err
	}
	return true, nil
}

func (cg *CardGenerator) storeCardNumber(ctx context.Context, iin, cardNumber string) error {
	// Start PostgreSQL transaction
	tx, err := cg.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}

	// Insert into PostgreSQL
	query := `INSERT INTO card_numbers (iin, card_number) VALUES ($1, $2)`
	_, err = tx.ExecContext(ctx, query, iin, cardNumber)
	if err != nil {
		tx.Rollback()
		return err
	}

	// Commit transaction
	err = tx.Commit()
	if err != nil {
		return err
	}

	err = cg.redis.Set(ctx, "card:"+cardNumber, iin, 0).Err()
	return err
}

func generateRandomCardNumber(iin string, minLength, maxLength int) string {
	length := minLength + rand.Intn(maxLength-minLength+1)
	cardNumber := iin

	for i := len(iin); i < length; i++ {
		cardNumber += strconv.Itoa(rand.Intn(10))
	}

	return cardNumber
}
```

3. Finally, create a table in your PostgreSQL database:

```sql
CREATE TABLE card_numbers (
    id SERIAL PRIMARY KEY,
    iin VARCHAR(6) NOT NULL,
    card_number VARCHAR(19) UNIQUE NOT NULL
);
```

Now you can run the generator, and it will generate unique card numbers, store them in PostgreSQL, and use Redis as a caching layer for checking existing card numbers. Remember to replace the connection strings and credentials for the PostgreSQL and Redis databases with your configurations.

It's important to note that generating 100kk (100 million) card numbers using the algorithm above will take a significant amount of time, especially when interacting with Redis and PostgreSQL. However, doing benchmark tests allows us to measure the performance of the algorithm itself in isolation. To do this, we can create a separate benchmark test file in the same directory, such as `cardgenerator_test.go`.

```go
package main

import (
	"context"
	"fmt"
	"os"
	"testing"

	"github.com/go-redis/redis/v8"
	"github.com/stretchr/testify/require"
)

type MockDBStorage struct{}

func (m *MockDBStorage) CheckIfExists(ctx context.Context, cardNumber string) (bool, error) {
	return false, nil
}

func (m *MockDBStorage) StoreCardNumber(ctx context.Context, iin, cardNumber string) error {
	return nil
}

func TestMain(m *testing.M) {
	rand.Seed(time.Now().UTC().UnixNano())
	os.Exit(m.Run())
}

func BenchmarkCardNumberGeneration(b *testing.B) {
	iin := "123456"

	redisClient := setupRedis()
	mockDB := &MockDBStorage{}

	cardGenerator := &CardGenerator{
		db:    mockDB,
		redis: redisClient,
	}

	count := 100_000_000
	workers := 100 // Adjust this value according to CPU cores

	ch := make(chan string, workers)

	b.ResetTimer()
	b.ReportAllocs()

	for i := 0; i < workers; i++ {
		go func() {
			for j := 0; j < b.N*count/workers; j++ {
				ctx := context.Background()
				cardNumber, err := cardGenerator.GenerateCardNumber(ctx, iin)
				require.NoError(b, err)
				ch <- cardNumber
			}
		}()
	}

	for i := 0; i < b.N*count; i++ {
		<-ch
	}
}

func BenchmarkRandomCardNumberGeneration(b *testing.B) {
	iin := "123456"

	b.ResetTimer()
	b.ReportAllocs()

	for i := 0; i < b.N; i++ {
		cardNumber := generateRandomCardNumber(iin, 16, 19)
		_ = cardNumber
	}
}
```

To run the benchmarks, use the following command:

```sh
$ go test -bench=. -benchtime=10s -benchmem
```

This command will run both the `BenchmarkCardNumberGeneration` and `BenchmarkRandomCardNumberGeneration` benchmarks with a duration of 10 seconds each.

Remember that the benchmark tests will use a mock DB storage to avoid executing real database operations. Keep in mind that the actual performance might be different when executing real database operations, and that the Redis cache might become a bottleneck depending on the available memory and dataset size.

