    transaction.Commit();
}

private void ExecuteNonQuery(string commandText)
{
    using var command = _connection.CreateCommand();
    command.CommandText = commandText;
    command.ExecuteNonQuery();
}
public void Dispose()
{
    _connection.Dispose();
}

