int main() {
    // 初始化H.265和AAC编解码器
    AVCodec *h264_codec = NULL, *aac_codec = NULL;
    h264_codec = avcodec_find_encoder(AV_CODEC_ID_H264);
    aac_codec = avcodec_find_encoder(AV_CODEC_ID_AAC);

