    AVPacket aacPkt;
    av_init_packet(&aacPkt);
    aacPkt.data = aac_buff;
    aacPkt.size = aac_size;

    // 对H.265和AAC数据进行解码或编码处理
    // ...

    // 准备返回结果
    AVPacket h264Pkt, aacPkt;
    h264Pkt = h265Pkt; // 编码结果H.264数据
    aacPkt = aacPkt; // 编码结果AAC数据

    // 释放分配的内存
    avcodec_close(h264_codec_ctx);
