Here's an extended version of the music bot including additional commands. Please make sure you have the latest versions of `discord.js`, `@discordjs/voice`, and `play-dl` installed.

```javascript
const { Client, Intents } = require('discord.js');
const { joinVoiceChannel, createAudioPlayer, createAudioResource, entersState, AudioPlayerStatus, VoiceConnectionStatus } = require('@discordjs/voice');
const { videoInfo, StreamExtractor } = require('play-dl');

const token = 'YOUR_BOT_TOKEN';
const client = new Client({ intents: [Intents.FLAGS.Guilds, Intents.FLAGS.GuildMessages, Intents.FLAGS.GuildVoiceStates] });

const queue = new Map();

client.on('ready', () => {
    console.log(`Logged in as ${client.user.tag}!`);
});

client.on('messageCreate', async message => {
    if (message.author.bot) return;

    const serverQueue = queue.get(message.guild.id);
    const voiceChannel = message.member.voice.channel;

    if (message.content.startsWith('!play')) {
        if (!voiceChannel) return message.reply('You must be in a voice channel to play music.');
        const permissions = voiceChannel.permissionsFor(message.client.user);
        if (!permissions.has('CONNECT') || !permissions.has('SPEAK')) {
            return message.reply('I need permission to join and speak in your voice channel.');
        }

        const song = message.content.split('!play ')[1];

        try {
            const info = await videoInfo(song);
            const stream = await StreamExtractor(song);
            const resource = createAudioResource(stream.stream, { inputType: stream.type, metadata: { title: info.videoDetails.title } });
            const songObject = {
                title: info.videoDetails.title,
                resource: resource
            };

            if (!serverQueue) {
                const queueBound = {
                    voiceChannel: voiceChannel,
                    connection: null,
                    songs: [],
                    player: createAudioPlayer(),
                    playing: true
                };

                queue.set(message.guild.id, queueBound);
                queueBound.songs.push(songObject);

                try {
                    const connection = joinVoiceChannel({
                        channelId: voiceChannel.id,
                        guildId: voiceChannel.guild.id,
                        adapterCreator: voiceChannel.guild.voiceAdapterCreator
                    });

                    queueBound.connection = connection;
                    play(message.guild.id, queueBound.songs[0]);
                } catch (error) {
                    console.error(error);
                    queue.delete(message.guild.id);
                    return message.reply('There was an error joining the voice channel.');
                }
            } else {
                serverQueue.songs.push(songObject);
                return message.channel.send(`**${songObject.title}** has been added to the queue.`);
            }

            return message.channel.send(`**${songObject.title}** is now playing.`);
        } catch (error) {
            console.error(error);
            return message.channel.send('There was an error playing the requested song.');
        }
    } else if (message.content === '!skip') {
        if (!voiceChannel) return message.reply('You must be in a voice channel to skip the song.');
        if (!serverQueue) return message.reply("There's no song to skip.");
        serverQueue.player.stop();
        return message.channel.send('Skipped the current song.');
    } else if (message.content === '!stop') {
        if (!voiceChannel) return message.reply('You must be in a voice channel to stop the music.');
        serverQueue?.player.stop();
        queue.delete(message.guild.id);
        return message.channel.send('Music stopped and queue cleared.');
    } else if (message.content === '!pause') {
        if (!voiceChannel) return message.reply('You must be in a voice channel to pause the music.');
        if (!serverQueue) return message.reply("There's no song to pause.");
        serverQueue.player.pause();
        return message.channel.send('Paused the music.');
    } else if (message.content === '!unpause') {
        if (!voiceChannel) return message.reply('You must be in a voice channel to unpause the music.');
        if (!serverQueue) return message.reply("There's no song to unpause.");
        serverQueue.player.unpause();
        return message.channel.send('Unpaused the music.');
    } else if (message.content === '!queue') {
        if (!serverQueue) return message.reply("There's no queue.");
        let queueMessage = 'Current queue:\n';
        serverQueue.songs.forEach((song, index) => {
            queueMessage += `${index + 1}. ${song.title}\n`;
        });
        return message.channel.send(queueMessage);
    } else if (message.content.startsWith('!remove')) {
        if (!serverQueue) return message.reply("There's no queue.");
        const songIndex = parseInt(message.content.split(' ')[1]) - 1;
        if (!Number.isInteger(songIndex) || songIndex < 0 || songIndex >= serverQueue.songs.length) {
            return message.reply('Invalid index.');
        }
        const removedSong = serverQueue.songs.splice(songIndex, 1);
        return message.channel.send(`Removed **${removedSong[0].title}** from the queue.`);
    } else if (message.content.startsWith('!seek')) {
        if (!serverQueue) return message.reply("There's no song to seek.");
        const time = parseInt(message.content.split(' ')[1]);
        if (!Number.isInteger(time) || time < 0) {
            return message.reply('Invalid time.');
        }
        serverQueue.player.seek(time * 1000);
        return message.channel.send(`Seeked the song to ${time} seconds.`);
    } else if (message.content.startsWith('!forward') || message.content.startsWith('!rewind')) {
        if (!serverQueue) return message.reply("There's no song to seek.");
        const offset = parseInt(message.content.split(' ')[1]);
        if (!Number.isInteger(offset) || offset < 0) {
            return message.reply('Invalid time.');
        }
        const currentPosition = serverQueue.player.playbackDuration / 1e3;
        const newPosition = message.content.startsWith('!forward') ? currentPosition + offset : currentPosition - offset;
        if (newPosition > 0) {
            serverQueue.player.seek(newPosition * 1e3);
            return message.channel.send(`${message.content.startsWith('!forward') ? 'Forwarded' : 'Rewinded'} the song by ${offset} seconds.`);
        } else {
            return message.reply('Cannot seek to a negative offset.');
        }
    } else if (message.content === '!nowplaying') {
        if (!serverQueue) return message.reply("There's no song playing.");
        return message.channel.send(`Now playing: **${serverQueue.songs[0].title}**`);
    } else if (message.content === '!join') {
        if (!voiceChannel) return message.reply('You have to be in a voice channel to request me to join.');
        if (serverQueue) return message.reply('I am already in the voice channel.');
        joinVoiceChannel({
            channelId: voiceChannel.id,
            guildId: voiceChannel.guild.id,
            adapterCreator: voiceChannel.guild.voiceAdapterCreator
        });
        return message.channel.send('Joined the voice channel.');
    } else if (message.content === '!leave') {
        if (!voiceChannel) return message.reply('You have to be in a voice channel to request me to leave.');
        if (!serverQueue) return message.reply("I'm not in a voice channel.");
        serverQueue.connection.destroy();
        queue.delete(message.guild.id);
        return message.channel.send('Left the voice channel.');
    }
});

async function play(guildId, song) {
    const queueBound = queue.get(guildId);
    if (!song) {
        queueBound.connection.destroy();
        queue.delete(guildId);
        return;
    }

    queueBound.connection.subscribe(queueBound.player);
    queueBound.player.play(song.resource);

    queueBound.player.on(AudioPlayerStatus.Idle, async () => {
        queueBound.songs.shift();
        play(guildId, queueBound.songs[0]);
    });

    try {
        await entersState(queueBound.connection, VoiceConnectionStatus.Ready, 15e3);
    } catch (error) {
        console.error(error);
        queue.delete(guildId);
        queueBound.connection.destroy();
    }
}

client.login(token);
```

This code adds the following commands to the music bot:

- **!skip**: Skips the current song and plays the next song in the queue.
- **!pause**: Pauses the current song.
- **!unpause**: Unpauses the paused song and resumes playing.
- **!queue**: Shows the current queue.
- **!remove [index]**: Removes the song at the specified index from the queue.
- **!seek [seconds]**: Seeks the current song to the specified time (in seconds).
- **!forward [seconds]**: Forwards the current song by the specified number of seconds.
- **!rewind [seconds]**: Rewinds the current song by the specified number of seconds.
- **!nowplaying**: Shows the current playing song.
- **!join**: Makes the bot join the voice channel.
- **!leave**: Makes the bot leave the voice channel.

