        e1.HasMorePages = false;

        while (linesPrinted < numLines)
        {
            if (yLineTop + lineHeight > y2Margin)
            {
                e1.HasMorePages = true;
                multiPage = true;
                pagesPrinted = PrintPageLine(font, yMargin, x2Margin, e1, pagesPrinted, y2Margin);

                return;
            }

            e1.Graphics.DrawString(
                str[linesPrinted],
                myFont,
                new SolidBrush(Color.Black),
                new PointF(xMargin, yLineTop));

            linesPrinted++;
            yLineTop += lineHeight;
        }

        if (multiPage)
        {
            PrintPageLine(font, yMargin, x2Margin, e1, pagesPrinted, y2Margin);
        }

        lastPrintedPage = e1.PageSettings.PrinterSettings.ToPage - 1;
    };

    if (OnPrintEnd != null)
    {
        p.EndPrint += (o, e) =>
        {
            OnPrintEnd?.Invoke();

            if (lastPrintedPage == p.PrinterSettings.PrintRange.EndPage - 1)
            {
                OnPrintCorrectly?.Invoke();
            }
        };
    }

    try
    {
        p.Print();
    }
    catch (Exception ex)
    {
        Log.Error(ex);
    }
}

private static int PrintPageLine(string font, int yMargin, float x2Margin, PrintPageEventArgs e1, int pagesPrinted, float y2Margin)
{
    e1.Graphics.DrawString(
        $"Page {pagesPrinted}",
        new Font(
            font,
            10,
            System.Drawing.FontStyle.Bold),
        new SolidBrush(Color.Black),
        new PointF(x2Margin - 70, y2Margin));

    pagesPrinted++;

    return pagesPrinted;
}
```

In this updated version, an OnPrintCorrectly event is added to the method signature. The PrintPage event handler updates the lastPrintedPage variable for each page that is printed, similar to the previous code example.

After the printing process is complete, the code checks if the lastPrintedPage is equal to the end page of the print range. If they are equal, then it invokes the OnPrintCorrectly event to indicate that the printing was successful.

Note that the PrintPageLine method in this example is not required and is only used to demonstrate how to update page numbers in a multipage document. If you don't need to update page numbers, you can remove this method.

