To make your code compatible with sqlite-net-pcl, you'll need to do the following:

1. Install the sqlite-net-pcl NuGet package:

```
Install-Package sqlite-net-pcl
```

2. Change the `SQLiteConnection` to `SQLiteAsyncConnection` and import the appropriate namespaces.

3. Use the attributes provided by sqlite-net-pcl for table and column mapping, such as `[Table]`, `[PrimaryKey]`, `[ForeignKey]`, and `[MaxLength]`.

4. Replace manual SQL commands with SQLiteAsyncConnection methods like `CreateTableAsync`, `InsertAsync`, and `UpdateAsync`.

5. Replace `ExecuteNonQuery` method calls with appropriate `sqlite-net-pcl` method calls.

Here's the modified code:

```csharp
using SQLite;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class SqLiteDatabase : IDisposable
{
    private readonly SQLiteAsyncConnection _connection;

    public SqLiteDatabase(string databaseName)
    {
        _connection = new SQLiteAsyncConnection(databaseName + ".sqlite");
        InitializeDatabaseAsync().Wait();
    }

    private async Task InitializeDatabaseAsync()
    {
        await _connection.CreateTableAsync<User>();
        await _connection.CreateTableAsync<Card>();
        await _connection.CreateTableAsync<UserCard>();
    }

    // ... (rest of the class)

}

[Table("Users")]
internal sealed class User
{
    [PrimaryKey]
    public string Id { get; set; }
    //...
}

[Table("Cards")]
internal sealed class Card
{
    [PrimaryKey]
    public string Id { get; set; }
    //...
}

[Table("UserCards")]
internal sealed class UserCard
{
    [PrimaryKey, Column("UserId"), ForeignKey("Users")]
    public string UserId { get; set; }

    [PrimaryKey, Column("CardId"), ForeignKey("Cards")]
    public string CardId { get; set; }

    public long Timestamp { get; set; }
}
```

