import org.java_websocket.client.WebSocketClient;
import org.java_websocket.handshake.ServerHandshake;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Scanner;

public class ChatGPTWebSocketClient extends WebSocketClient {

    private Scanner scanner;

    public ChatGPTWebSocketClient(URI serverUri) {
        super(serverUri);
        scanner = new Scanner(System.in);
    }

    @Override
    public void onOpen(ServerHandshake handshakedata) {
        System.out.println("Connected to ChatGPT!");
    }

    @Override
    public void onMessage(String message) {
        System.out.println("ChatGPT: " + message);
        String response = scanner.nextLine();
        send(response);
    }

    @Override
    public void onClose(int code, String reason, boolean remote) {
        System.out.println("Disconnected from ChatGPT!");
    }

    @Override
    public void onError(Exception ex) {
        ex.printStackTrace();
    }

    public static void main(String[] args) {
        try {
            ChatGPTWebSocketClient client = new ChatGPTWebSocketClient(new URI("wss://huggingface.co/spaces/yuntian-deng/ChatGPT"));
            client.connect();
        } catch (URISyntaxException ex) {
            ex.printStackTrace();
        }
    }
}
