```java
class Solution {
    public List<List<Integer>> findSubsequences(int[] nums) {
        List<List<Integer>> ans = new ArrayList<>();
        dfs(nums, 0, new ArrayList<>(), ans);
        return ans;
    }

    private void dfs(int[] nums, int index, List<Integer> tempList, List<List<Integer>> ans) {
        if (tempList.size() >= 2) {
            ans.add(new ArrayList<>(tempList));
        }

        if (index == nums.length) {
            return;
        }

        Integer lastUsed = null;
        for (int i = index; i < nums.length; i++) {
            if (lastUsed != null && nums[i] == lastUsed) {
                continue;
            }
            if (tempList.isEmpty() || tempList.get(tempList.size() - 1) <= nums[i]) {
                tempList.add(nums[i]);
                dfs(nums, i + 1, tempList, ans);
                tempList.remove(tempList.size() - 1);
                lastUsed = nums[i];
            }
        }
    }
}
