void RollPollingWorker::Runnable() {
    std::string prefix = Prefix();
    AVPacket* pkt = av_packet_alloc(); //分配AVPacket
    while (kRunning == state_) { //当任务处于运行状态时
        std::lock_guard<std::mutex> lock(mutex_);
        SourceContext* source = source_ctx_.get(); //获取输入源上下文
        FilterContext* filter = filter_ctx_.get(); //获取过滤器上下文

        int ret = av_read_frame(source->fmt_ctx_, pkt); //读取帧
        if (ret < 0) {
            if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)
                ret = 0;
            break;
        }

        //只处理视频流
        if (pkt->stream_index != source->vid_stream_idx_)
            continue;

        if (filter_ctx_) { //如果存在过滤器上下文
            ret = avcodec_send_packet(source->codec_ctx_, pkt); //将数据包发送到解码器
            if (ret < 0) {
                if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)
                    ret = 0;
                break;
            }

            while (ret >= 0) {
                ret = avcodec_receive_frame(source->codec_ctx_, source->decoded_frame_); //接收解码后的帧
                if (ret < 0) {
                    if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)
                        ret = 0;
                    break;
                }

                FilterFrame(filter, source->decoded_frame_); //过滤帧
                av_frame_unref(source->decoded_frame_); //取消引用帧
            }
        } else {
            pkt->stream_index = 0;
            pkt->pts = pkt->dts = (frame_cnt_++) * 40;
            pkt->duration = 0;
            pkt->pos = -1;
            ret = av_interleaved_write_frame(ofmt_ctx_, pkt); //将数据包写入输出文件
        }

        av_packet_unref(pkt); //取消引用数据包
        if (ret < 0) {
            ErrorL << prefix << " write packet to output file failed \n";
            //break;
        }
    }

    av_write_trailer(ofmt_ctx_); //写入文件尾部
    av_packet_free(&pkt); //释放数据包

    avcodec_free_context(&ocodec_ctx_); //释放编码器上下文
    if (ofmt_ctx_ && !(ofmt_ctx_->oformat->flags & AVFMT_NOFILE)) //如果输出格式上下文存在且不是没有文件标志
        avio_closep(&ofmt_ctx_->pb); //关闭输出文件
    avformat_free_context(ofmt_ctx_);    //释放输出格式上下文
    state_ = kStoped; //设置状态为停止
    InfoL << "roll polling task finished"; //输出任务完成信息
}

