        this.isCalledViaProxy = value;
    }

    // Other methods ...

    @Override
    public void upgrade() {
        if (!isCalledViaProxy) {
            System.out.println("Please use proxy to call this method!");
            return;
        }

        if (this.proxy == null) {
            System.out.println("Please get proxy!");
        } else {
