```

2. Include reqwest in your `main.rs`:

```rust
use ethers::prelude::*;
use ethers::providers::{Http, Middleware};
use std::convert::TryInto;
use std::str::FromStr;
use tokio::runtime::Runtime;
```

3. Add a new function to create a BSC provider:

```rust
async fn create_bsc_provider() -> Provider<Http> {
    // Binance Smart Chain Testnet RPC URL
    let bsc_rpc_url = "https://data-seed-prebsc-1-s1.binance.org:8545/";

    let provider = Provider::<Http>::try_from(bsc_rpc_url)
        .expect("Could not create BSC provider");

    provider
}
```

4. Use the provider in main function while showing the wallet's balance:

```rust
fn main() {
    let rt = Runtime::new().unwrap();
    rt.block_on(async {
        // Generate a new wallet.
        let wallet = generate_wallet().await;

        // Connect to the BSC Testnet.
