   ```java
   public class MyJob {

       public static void main(String[] args) throws Exception {

           // 定义Flink环境，初始化参数等
           StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
           env.setParallelism(1);

           // 完成对mybatis-plus的初始化，并将SqlSessionFactory注册到全局传递
           final Configuration conf = new Configuration();
           conf.setBoolean(ConfigConstants.SQL_CLIENT_SESSION_DAEMON_THREAD_ENABLE, true);
           conf.setString(ConfigConstants.FLINK_PLUGIN_BASE_DIR_PATH, "/path/to/flink/plugins");
           conf.setString(ConfigConstants.SQL_CLASSLOADER_PARENT_FIRST_PREFIXES, "com.baomidou.mybatisplus");

           ClassLoader loader = Thread.currentThread().getContextClassLoader();
           Resource resource = new ClassPathResource("mybatis-config.xml");
           InputStream stream = resource.getInputStream();
           conf.setBoolean(ConfigOptions.SQL_EXEC_DROP_TEMPORARY_TABLES_ON_CLOSE, true);

           Properties properties= new Properties();
           properties.setProperty("driverClassName", "com.mysql.cj.jdbc.Driver");
           properties.setProperty("jdbcUrl", "jdbc:mysql://localhost:3306/flink_test?characterEncoding=utf8");
           properties.setProperty("username", "root");
           properties.setProperty("password", "root");

           //注册 Data Source
           BasicDataSource dataSource = new BasicDataSource();
           dataSource.setDriverClassName(properties.getProperty("driverClassName"));
           dataSource.setUrl(properties.getProperty("jdbcUrl"));
           dataSource.setUsername(properties.getProperty("username"));
           dataSource.setPassword(properties.getProperty("password"));
           conf.setString("sql-env.jdbc.url", "jdbc:mysql://localhost:3306/flink_test?characterEncoding=utf8");
           conf.setString("sql-env.jdbc.username", "root");
           conf.setString("sql-env.jdbc.password", "root");

           conf.setString("sql.env.default-database", "flink_test");
           conf.setString("sql-env.lookup.cache.max-rows", "1000000");
           StreamTableEnvironment tEnv = StreamTableEnvironment.create(
                   env,
                   EnvironmentSettings.newInstance().useBlinkPlanner().inStreamingMode().build(),
                   new TableConfig()
                           .setSubsectionOptimization(true)
                           .setIdleStateRetentionTime(Time.hours(72), Time.hours(96))
           );
           tEnv.getConfig().setSqlDialect(SqlDialect.DEFAULT);
           tEnv.getConfig().getConfiguration().addAll(conf);

           VariableSubstitutor substitutor = new TestVariableSubstitutor();
           tEnv.getCatalog(tEnv.getCurrentCatalog()).get().getFactory().createCatalogFunction("substituteVariables", substitutor);
           tEnv.registerFunction("substituteVariables", new ScalarFunction() {
               private static final long serialVersionUID = -4174732384694994715L;
               @DataTypeHint(DataType.STRING)
               public String eval(String s) {
                   try {
                       return substitutor.substitute(s);
                   } catch (VariableSubstitutionException | RuntimeException e) {
                       throw new RuntimeException(e);
                   }
               }
           });

           // 初始化MyBatis SqlSessionFactory
           SqlSessionFactory sessionFactory = new SqlSessionFactoryBuilder().build(stream, null, properties);
           conf.set(ConfigConstants.KEYED_STATE_BACKEND, "rocksdb");
           conf.setString(ConfigConstants.CHECKPOINT_STORAGE, "file:///tmp/checkpoints/");
           env.getConfig().setGlobalJobParameters(conf);
           env.getConfig().enableObjectReuse();

           env.addSource(new MySource(userService)) // 从数据源读取数据
                   .addSink(new MySink(sessionFactory)) // 将数据写入Sink
                   .setParallelism(1);

            env.execute();
       }
   }
   ```

