```javascript
const rotatingCubeGeometry = new THREE.BoxGeometry(1, 1, 1);
const rotatingCubeMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
const rotatingCube = new THREE.Mesh(rotatingCubeGeometry, rotatingCubeMaterial);

scene.add(rotatingCube);

const radius = 5; // Радиус вращения объекта
const rotationSpeed = 0.02; // Скорость вращения объекта

function animate() {
    requestAnimationFrame(animate);

    uniforms.mouseCoord.value.x = currentX;
    uniforms.mouseCoord.value.y = -currentY + window.innerHeight;

    // Обновление положения и вращения объекта вокруг указанных координат
    rotatingCube.position.x = currentX + radius * Math.cos(time * rotationSpeed);
    rotatingCube.position.y = -currentY + window.innerHeight + radius * Math.sin(time * rotationSpeed);
    rotatingCube.rotation.x += rotationSpeed;
    rotatingCube.rotation.y += rotationSpeed;
    rotatingCube.rotation.z += rotationSpeed;
}

```

