using Microsoft.Maui.Controls;
using Comet;
using Comet.Controls;
using System;
using System.Collections.Generic;
using System.Diagnostics;

namespace <%= namespaceName %>
{
    public class CounterApp : DotNetMauiExperimentApp<CounterState>
    {
        public CounterApp() : base() { }

        [Body]
        Microsoft.Maui.View View(CounterState state) =>
            new Grid()
            {
                new ColumnDefinition() { Width = GridLength.Star },
                new ColumnDefinition() { Width = GridLength.Star },
                new Label { Text = $"You clicked {state.Count} times", HorizontalOptions = LayoutOptions.Center },
                new Button { Text = "Click Me!", Command = new Command(() => Dispatch(new IncrementCounter())) }
            }
            .RowDefinitions(r =>
            {
                r.Add(new RowDefinition { Height = GridLength.Star });
                r.Add(new RowDefinition { Height = GridLength.Star });
            })
            .AssignChildren(
                (c, r) =>
                {
                    c[0, 0] = r.IfTypeIs<Label>();
                    c[1, 1] = r.IfTypeIs<Button>();
                });

        protected override CounterState InitialState => new CounterState(0);

        protected override IReadOnlyList<IMiddleware<Message, CounterState>> GetMiddleware() => new List<IMiddleware<Message, CounterState>>
        {
            new DefaultMiddleware<Message, CounterState>().Trace(MessageDumper)
        };

        CounterState Reducer(CounterState state, Message message) =>
            message is IncrementCounter
            ? state with { Count = state.Count + 1 }
            : null;

        IReadOnlyList<Message> RunEffects(CounterState state, Message message) =>
            Array.Empty<Message>();

        protected override AppState<CounterState> BuildApp()
        {
            return new AppState<CounterState>(
                GetMiddleware(),
                InitialState,
                Reducer,
                RunEffects);
        }

        void MessageDumper(Message message) { Debug.WriteLine($"Message: {message}"); }
    }

    public class IncrementCounter : Message { }
}
```

