```javascript
const startUrl = "https://arcjav.arcjavdb.workers.dev/0:/001-050/上原亚衣/";

// Get the URLs of image and movie links
async function getLinks(url) {
  const response = await fetch(url);
  const text = await response.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, "text/html");

  const folderSelector = "a.list-group-item:nth-child(1)";
  const itemSelector = "div.list-group-item:nth-child(5) > a:nth-child(2)";

  const folderLinks = Array.from(doc.querySelectorAll(folderSelector)).map(a => a.href);
  const itemLinks = Array.from(doc.querySelectorAll(itemSelector)).map(a => a.href);

  return { folderLinks, itemLinks };
}

// Scrape the content recursively
async function scrapeContent(url) {
  const { folderLinks, itemLinks } = await getLinks(url);

  console.log("Scraped: ", url);
  console.log("Movie & Image Links: ", itemLinks);

  for (const folderLink of folderLinks) {
    await scrapeContent(folderLink);
  }
}

scrapeContent(startUrl);
```

This code will log all the movie and image links to the console for each folder it goes through. You can later customize it to save or download the content based on your needs. Note that this code might not work if there's any CORS restriction on the website you're trying to scrape. To bypass CORS limitations, it might be necessary to use an external proxy, a CORS extension, or a headless browser like Puppeteer to perform the request.

