Below is a HighSum card game written in Java that can be run in an IDE, using the provided Keyboard class:

```java
public class HighSumGame {
    public static void main(String[] args) {
        Keyboard keyboard = new Keyboard();

        System.out.println("HighSum GAME");
        System.out.println("================================================================================");

        String playerName = keyboard.readString("Enter Login name: ");
        String playerPassword = keyboard.readString("Enter Password: ");

        Player player = new Player(playerName, playerPassword, 100);
        Dealer dealer = new Dealer();
        Deck deck = new Deck();

        while (true) {
            System.out.println("================================================================================");
            System.out.println(playerName + ", You have " + player.getChips() + " chips");

            // Game start
            System.out.println("--------------------------------------------------------------------------------");
            System.out.println("Game starts - Dealer shuffles deck.");
            System.out.println("--------------------------------------------------------------------------------");

            deck.shuffle();
            dealer.resetHand();
            player.resetHand();

            // Deal initial cards
            for (int i = 0; i < 2; i++) {
                player.addCard(deck.dealCard());
                dealer.addCard(deck.dealCard());
            }

            // Gameplay loop
            boolean gameEnded = false;
            int betOnTable = 0;
            for (int round = 1; round <= 4 && !gameEnded; round++) {
                System.out.println("Dealer dealing cards - ROUND " + round);

                if (round > 1) {
                    Card newCard = deck.dealCard();
                    player.addCard(newCard);
                    dealer.addCard(newCard);
                }

                player.showVisibleCards(round);
                dealer.showVisibleCards(round);

                if (player.getTotalVisibleCardValue(round) >= dealer.getTotalVisibleCardValue(round)) {
                    int playerBet = keyboard.readInt("Player call, state bet: ");
                    player.deductChips(playerBet);
                    betOnTable += playerBet * 2;

                    System.out.println(playerName + ", You are left with " + player.getChips() + " chips");
                    System.out.println("Bet on table : " + betOnTable);
                } else {
                    System.out.println("Dealer call, state bet: 10");
                    player.deductChips(10);
                    betOnTable += 20;

                    boolean isFollowing = keyboard.readBoolean("Do you want to follow? [Y/N]: ");

                    if (!isFollowing) {
                        System.out.println(playerName + " quits the game!");
                        gameEnded = true;
                        continue;
                    }

                    System.out.println(playerName + ", You are left with " + player.getChips() + " chips");
                    System.out.println("Bet on table : " + betOnTable);
                }
            }

            if (!gameEnded) {
                System.out.println("--------------------------------------------------------------------------------");
                System.out.println("Game End - Dealer reveal hidden cards");
                dealer.revealHiddenCard();
                dealer.showCardsOnHand();
                System.out.println("Value : " + dealer.getTotalCardsValue());

                player.showCardsOnHand();
                System.out.println("Value : " + player.getTotalCardsValue());

                if (player.getTotalCardsValue() > dealer.getTotalCardsValue()) {
                    System.out.println(playerName + " Wins");
                    player.addChips(betOnTable);
                    System.out.println(playerName + ", You have " + player.getChips() + " chips");
                } else {
                    System.out.println("Dealer Wins");
                }
            }

            deck.appendCard(player.getCardsOnHand());
            deck.appendCard(dealer.getCardsOnHand());

            System.out.println("Dealer shuffles used cards and place behind the deck.");
            System.out.println("--------------------------------------------------------------------------------");

            boolean nextGame = keyboard.readBoolean("Next Game? (Y/N) : ");
            if (!nextGame) {
                break;
            }
        }

        System.out.println("Thanks for playing HighSum card game!");
    }
}
