Certainly! Here's an example of a 3D pyramid (tetrahedron) using OpenGL in C++:

```cpp
#include <GL/glut.h>

// Global variables
GLuint PyramidList;
float Angle = 0.0f;

// Initialize the pyramid object
void InitPyramid() {
    const float P1[] = {-1.0f, -1.0f,  1.0f};
    const float P2[] = { 1.0f, -1.0f,  1.0f};
    const float P3[] = { 0.0f,  1.0f,  0.0f};
    const float P4[] = { 0.0f, -1.0f, -1.0f};

    PyramidList = glGenLists(1);
    glNewList(PyramidList, GL_COMPILE);

    glBegin(GL_TRIANGLES);

    // Front face
    glColor3f(1.0f, 0.0f, 0.0f);
    glVertex3fv(P1);
    glVertex3fv(P2);
    glVertex3fv(P3);

    // Right face
    glColor3f(0.0f, 1.0f, 0.0f);
    glVertex3fv(P2);
    glVertex3fv(P4);
    glVertex3fv(P3);

    // Left face
    glColor3f(0.0f, 0.0f, 1.0f);
    glVertex3fv(P1);
    glVertex3fv(P3);
    glVertex3fv(P4);

    // Bottom face
    glColor3f(1.0f, 1.0f, 0.0f);
    glVertex3fv(P1);
    glVertex3fv(P4);
    glVertex3fv(P2);

    glEnd();

    glEndList();
}

// Display function
void Display() {
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    glLoadIdentity();

    glTranslatef(0.0f, 0.0f, -6.0f);
    glRotatef(Angle, 0.0f, 1.0f, 0.0f);

    glCallList(PyramidList);

    glutSwapBuffers();
}

// Idle function for animation
void Idle() {
    Angle += 0.5f;
    if (Angle > 360.0f) {
        Angle -= 360.0f;
    }
    glutPostRedisplay();
}

// Main function
int main(int argc, char** argv) {
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_DOUBLE | GLUT_RGB | GLUT_DEPTH);
    glutInitWindowSize(800, 600);
    glutCreateWindow("3D Pyramid");

    glEnable(GL_DEPTH_TEST);

    InitPyramid();

    glutDisplayFunc(Display);
    glutIdleFunc(Idle);

    glutMainLoop();
    return 0;
}
```

