private IEnumerator HeadbobCoroutine()
{
    float timer = 0.0f;

    Vector3 initialPosition = playerCamera.transform.localPosition;

    while (timer < Mathf.PI)
    {
        float moveAmount = Mathf.Sin(timer) * headbobAmount;

        playerCamera.transform.localPosition = initialPosition + new Vector3(0, moveAmount, 0);

