    void Awake()
    {
        playerCamera = GetComponentInChildren<Camera>();
        CharacterController = GetComponent<CharacterController>();
        defaultYPos = playerCamera.transform.localPosition.y;
        defaultFOV = playerCamera.fieldOfView;
        currentStamina = maxStamina;
        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;
    }

    void Update()
    {
        if(canMove)
        {
            HandleMovementInput();
            HandleMouseLook();

            if (CharacterController.velocity.y < 0 && !CharacterController.isGrounded)
                wasFalling = true;

            if (canJump)
                HandleJump();

            if(canCrouch)
                HandleCrouch();

            if (canUseHeadbob)
                HandleHeadbob();

            if (canZoom)
                HandleZoom();

            if (useFootsteps)
                HandleFootsteps();

            if(canInteract)
            {
                HandleInteractionCheck();
                HandleInteractionInput();
            }

            if (useStamina)
                HandleStamina();

            ApplyFinalMovements();
        }
    }

    private void HandleMovementInput()
    {
        currentInput = new Vector2((isCrouching ? crouchSpeed : isSprinting ? sprintSpeed : walkSpeed) * Input.GetAxis("Vertical"), (isCrouching ? crouchSpeed : isSprinting ? sprintSpeed : walkSpeed) * Input.GetAxis("Horizontal"));

        float moveDirectionY = moveDirection.y;
        moveDirection = (transform.TransformDirection(Vector3.forward) * currentInput.x) + (transform.TransformDirection(Vector3.right) * currentInput.y);
        moveDirection.y = moveDirectionY;
    }

    private void HandleMouseLook()
    {
        rotationX -= Input.GetAxis("Mouse Y") * lookSpeedY;
        rotationX = Mathf.Clamp(rotationX, -upperLookLimit, lowerLookLimit);
        playerCamera.transform.localRotation = Quaternion.Euler(rotationX, 0, 0);
        transform.rotation *= Quaternion.Euler(0, Input.GetAxis("Mouse X") * lookSpeedX, 0);
    }

    private void HandleJump()
    {
        if (shouldJump && !isCrouching && currentStamina >= jumpStaminaLoss)
        {
            int layerMask = (-1) - (1 << LayerMask.NameToLayer("Player"));
            if (Physics.Raycast(playerCamera.transform.position, Vector3.down, out RaycastHit hit, 3, layerMask))
            {
                switch (hit.collider.tag)
                {
                    case "Footsteps/GRASS":
                        jumpAudioSource.PlayOneShot(grassJumpClips[UnityEngine.Random.Range(0, grassJumpClips.Length - 1)]); 
                        break;
                    case "Footsteps/WOOD":
                        jumpAudioSource.PlayOneShot(woodJumpClips[UnityEngine.Random.Range(0, woodJumpClips.Length - 1)]);
                        break;
                    case "Footsteps/METAL":
                        jumpAudioSource.PlayOneShot(metalJumpClips[UnityEngine.Random.Range(0, metalJumpClips.Length - 1)]);
                        break;
                    case "Footsteps/GRAVEL":
                        jumpAudioSource.PlayOneShot(gravelJumpClips[UnityEngine.Random.Range(0, gravelJumpClips.Length - 1)]);
                        break;
                    case "Footsteps/CONCRETE":
                        jumpAudioSource.PlayOneShot(concreteJumpClips[UnityEngine.Random.Range(0, concreteJumpClips.Length - 1)]);
                        break;
                    default:
                        jumpAudioSource.PlayOneShot(concreteJumpClips[UnityEngine.Random.Range(0, concreteJumpClips.Length - 1)]);
                        break;
                } 
            }
            moveDirection.y = jumpForce;
            StartCoroutine(JumpHeadBob());
        }
        HandleLanding();
    }
    private IEnumerator JumpHeadBob()
    {
        float timeElapsed = 0;
        Vector3 initialCameraPosition = playerCamera.transform.localPosition;

        while (timeElapsed < headBobDuration)
        {
            float yOffset = Mathf.Sin(timeElapsed / headBobDuration * Mathf.PI) * headBobHeightAmplitude;
            playerCamera.transform.localPosition = new Vector3(initialCameraPosition.x, initialCameraPosition.y + yOffset, initialCameraPosition.z);

            float zRotation = Mathf.Sin(timeElapsed / headBobDuration * Mathf.PI * 2) * headBobRotationAmplitude;

            // Get the current X rotation of the camera.
            float xRotation = playerCamera.transform.localRotation.eulerAngles.x;

            // Apply the updated rotation.
            playerCamera.transform.localRotation = Quaternion.Euler(xRotation, 0, zRotation);

            timeElapsed += Time.deltaTime;
            yield return null;
        }

        playerCamera.transform.localPosition = initialCameraPosition;
    }

    private void HandleLanding()
    {
            int layerMask = (-1) - (1 << LayerMask.NameToLayer("Player"));
            if (Physics.Raycast(playerCamera.transform.position, Vector3.down, out RaycastHit hit, 3, layerMask) && CharacterController.isGrounded && wasFalling)
            {
                switch (hit.collider.tag)
                { 
                    case "Footsteps/GRASS":
                        landingAudioSource.PlayOneShot(grassLandClips[UnityEngine.Random.Range(0, grassLandClips.Length - 1)]);
                        break;
                    case "Footsteps/WOOD":
                        landingAudioSource.PlayOneShot(woodLandClips[UnityEngine.Random.Range(0, woodLandClips.Length - 1)]);
                        break;
                    case "Footsteps/METAL":
                        landingAudioSource.PlayOneShot(metalLandClips[UnityEngine.Random.Range(0, metalLandClips.Length - 1)]);
                        break;
                    case "Footsteps/GRAVEL":
                        landingAudioSource.PlayOneShot(gravelLandClips[UnityEngine.Random.Range(0, gravelLandClips.Length - 1)]);
                        break;
                    case "Footsteps/CONCRETE":
                        landingAudioSource.PlayOneShot(concreteLandClips[UnityEngine.Random.Range(0, concreteLandClips.Length - 1)]);
                        break;
                    default:
                        landingAudioSource.PlayOneShot(concreteLandClips[UnityEngine.Random.Range(0, concreteLandClips.Length - 1)]);
                        break;
                }
            wasFalling = false;
        }
    }

    private void HandleCrouch()
    {
        if (shouldCrouch)
            StartCoroutine(CrouchStand());
    }

    private void HandleHeadbob()
    {
        if (!CharacterController.isGrounded) return;

        if(Mathf.Abs(moveDirection.x) > 0.1f || Mathf.Abs(moveDirection.z) > 0.1f)
        {
            timer += Time.deltaTime * (isCrouching ? crouchBobSpeed : isSprinting ? sprintBobSpeed : walkBobSpeed);
            playerCamera.transform.localPosition = new Vector3(
                playerCamera.transform.localPosition.x,
                defaultYPos + Mathf.Sin(timer) * (isCrouching ? crouchBobAmount : isSprinting ? sprintBobAmount : walkBobAmount),
                playerCamera.transform.localPosition.z);
        }
    }

    private void HandleStamina()
    {
        if(isSprinting && currentInput != Vector2.zero && !isCrouching)
        {
            if(regeneratingStamina != null)
            {
                StopCoroutine(regeneratingStamina);
                regeneratingStamina = null;
            }

            currentStamina -= staminaMultiplier * Time.deltaTime;

            if(currentStamina < 0)
                currentStamina = 0;

            OnStaminaChange?.Invoke(currentStamina);

            if(currentStamina <= 0)
                canSprint = false;
        }

        if(wasFalling && !isCrouching)
        {
            if (regeneratingStamina != null)
            {
                StopCoroutine(regeneratingStamina);
                regeneratingStamina = null;
            }

            currentStamina -= jumpStaminaLoss;

            if (currentStamina < 0)
                currentStamina = 0;

            OnStaminaChange?.Invoke(currentStamina);

            if (currentStamina <= 0)
                canSprint = false;
        }

        if(!isSprinting && !wasFalling && currentStamina < maxStamina && regeneratingStamina == null)
        {
            regeneratingStamina = StartCoroutine(RegenStamina());
        }
    }

    private void HandleZoom()
    {
        if(Input.GetKeyDown(zoomKey))
        {
            if(zoomRoutine != null)
            {
                StopCoroutine(zoomRoutine);
                zoomRoutine = null;
            }

            zoomRoutine = StartCoroutine(ToggleZoom(true));
        }

        if (Input.GetKeyUp(zoomKey))
        {
            if (zoomRoutine != null)
            {
                StopCoroutine(zoomRoutine);
                zoomRoutine = null;
            }

            zoomRoutine = StartCoroutine(ToggleZoom(false));
        }
    }

    private void HandleInteractionCheck()
    {
        if(Physics.Raycast(playerCamera.ViewportPointToRay(interactionRayPoint), out RaycastHit hit, interactionDistance))
        {
            if(hit.collider.gameObject.layer == 7 && (currentInteractable == null || hit.collider.gameObject.GetInstanceID() != currentInteractable.GetInstanceID()))
            {
                hit.collider.TryGetComponent(out currentInteractable);

                if(currentInteractable)
                    currentInteractable.OnFocus();
            }
        }
        else if(currentInteractable)
        {
            currentInteractable.OnLoseFocus();
            currentInteractable = null;
        }
    }

    private void HandleInteractionInput()
    {
        if(Input.GetKeyDown(interactKey) && currentInteractable != null && Physics.Raycast(playerCamera.ViewportPointToRay(interactionRayPoint), out RaycastHit hit, interactionDistance, interactionLayer))
        {
            currentInteractable.OnInteract();
        }
    }

    private void HandleFootsteps()
    {
        if (!CharacterController.isGrounded) return;
        if (currentInput == Vector2.zero) return;

        footstepTimer -= Time.deltaTime;
        if(footstepTimer <= 0)
        {
            int layerMask = (-1) - (1 << LayerMask.NameToLayer("Player"));
            if (Physics.Raycast(playerCamera.transform.position, Vector3.down, out RaycastHit hit, 3, layerMask))
            {
                switch(hit.collider.tag)
                {
                    case "Footsteps/GRASS":
                        footstepAudioSource.PlayOneShot(grassWalkClips[UnityEngine.Random.Range(0, grassWalkClips.Length -1)]);
                        break;
                    case "Footsteps/WOOD":
                        footstepAudioSource.PlayOneShot(woodWalkClips[UnityEngine.Random.Range(0, woodWalkClips.Length - 1)]);
                        break;
                    case "Footsteps/METAL":
                        footstepAudioSource.PlayOneShot(metalWalkClips[UnityEngine.Random.Range(0, metalWalkClips.Length - 1)]);
                        break;
                    case "Footsteps/GRAVEL":
                        footstepAudioSource.PlayOneShot(gravelWalkClips[UnityEngine.Random.Range(0, gravelWalkClips.Length - 1)]);
                        break;
                    case "Footsteps/CONCRETE":
                        footstepAudioSource.PlayOneShot(concreteWalkClips[UnityEngine.Random.Range(0, concreteWalkClips.Length - 1)]);
                        break;
                    default:
                        footstepAudioSource.PlayOneShot(concreteWalkClips[UnityEngine.Random.Range(0, concreteWalkClips.Length - 1)]);
                        break;
                }
            }

            footstepTimer = GetCurrentOffset;
        }
    }

    private void ApplyFinalMovements()
    {
        if(!CharacterController.isGrounded)
            moveDirection.y -= gravity * Time.deltaTime;

        if (CharacterController.velocity.y < -1 && CharacterController.isGrounded)
            moveDirection.y = 0;

        if (willSlopeSlide && IsSliding)
            moveDirection += new Vector3(hitPointNormal.x, -hitPointNormal.y, hitPointNormal.z) * slopeSpeed;

        CharacterController.Move(moveDirection * Time.deltaTime);
    }

    private IEnumerator CrouchStand()
    {
        if (isCrouching && Physics.Raycast(playerCamera.transform.position, Vector3.up, 1f))
            yield break;

        duringCrouchAnim = true;

        float timeElapsed = 0;
        float targetHeight = isCrouching ? standingHeight : crouchHeight;
        float currentHeight = CharacterController.height;
        Vector3 targetCenter = isCrouching ? standingCenter : crouchingCenter;
        Vector3 currentCenter = CharacterController.center;

        while(timeElapsed < timeToCrouch)
        {
            CharacterController.height = Mathf.Lerp(currentHeight, targetHeight, timeElapsed / timeToCrouch);
            CharacterController.center = Vector3.Lerp(currentCenter, targetCenter, timeElapsed / timeToCrouch);
            timeElapsed += Time.deltaTime;
            yield return null;
        }

        CharacterController.height = targetHeight;
        CharacterController.center = targetCenter;

        isCrouching = !isCrouching;

        duringCrouchAnim = false;
    }

    private IEnumerator ToggleZoom(bool isEnter)
    {
        float targetFOV = isEnter ? zoomFOV : defaultFOV;
        float startingFOV = playerCamera.fieldOfView;
        float timeElapsed = 0;

        while(timeElapsed < timeToZoom)
        {
            playerCamera.fieldOfView = Mathf.Lerp(startingFOV, targetFOV, timeElapsed / timeToZoom);
            timeElapsed += Time.deltaTime;
            yield return null;
        }

        playerCamera.fieldOfView = targetFOV;
        zoomRoutine = null;
    }

    private IEnumerator RegenStamina()
    {
        yield return new WaitForSeconds(timeBeforeStaminaRegen);
        WaitForSeconds timeToWait = new WaitForSeconds(staminaTimeIncrement);

        while(currentStamina < maxStamina)
        {
            if (currentStamina > 0)
                canSprint = true;

            currentStamina += staminaValueIncrement;

            if (currentStamina > maxStamina)
                currentStamina = maxStamina;

            OnStaminaChange?.Invoke(currentStamina);

            yield return timeToWait;
        }

        regeneratingStamina = null;
    }
}

To run a coroutine within Jetpack Compose, you can use the `LaunchedEffect` function. `LaunchedEffect` is a Composable function that can be used to launch a coroutine when a key changes.

Here's an example of how to use `LaunchedEffect` to run a coroutine:

```kotlin
@Composable
fun SomeComposable() {
    val someState by remember { mutableStateOf("") }

    LaunchedEffect(someState) {
        val result = withContext(Dispatchers.IO) {
            // Perform some IO operation
        }

        someState = result
    }
}
```

In this example, `someState` is a mutable state variable that is being observed by `LaunchedEffect`. When `someState` changes, `LaunchedEffect` will launch a coroutine and perform some IO operation using the `withContext` function. Once the IO operation completes, the result will be saved to `someState`, triggering a recomposition of the composable.

Note that `withContext` is used to switch to the `Dispatchers.IO` context, which is a good practice when performing IO operations. You can switch to other contexts such as `Dispatchers.Main`, `Dispatchers.Default`, or `Dispatchers.IO` depending on your use case.

To create a Room database and set its values when it is not null, follow these steps:

1. Add the necessary dependencies to your project by adding the Room dependencies to your app-level build.gradle file:

```groovy
implementation "androidx.room:room-runtime:$room_version"
kapt "androidx.room:room-compiler:$room_version"
```

2. Create an entity class for the data you want to store in the Room database. For example, if you want to store a User object, create a User entity class:

```kotlin
@Entity(tableName = "users")
data class User(
    @PrimaryKey val id: Int,
    val name: String
)
```

3. Create a Room database class that extends RoomDatabase and includes your entity class. For example:

```kotlin
@Database(entities = [User::class], version = 1)
abstract class MyDatabase : RoomDatabase() {
    abstract fun userDao(): UserDao
}
```

4. Create a DAO (Data Access Object) interface to define the database operations you want to perform. For example:

```kotlin
@Dao
interface UserDao {
    @Query("SELECT * FROM users")
    fun getAllUsers(): List<User>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    fun insertUser(user: User)
}
```

5. Initialize your database using `Room.databaseBuilder`. Here's an example of how to create a database and set its values:

```kotlin
val db = Room.databaseBuilder(applicationContext, MyDatabase::class.java, "mydatabase")
        .fallbackToDestructiveMigration()
        .build()

if (db != null) {
    val userDao = db.userDao()

    // Perform database operations
    userDao.insertUser(User(1, "Alice"))
}
```

In this example, we create a Room database called `mydatabase` using `databaseBuilder`. We check if the database is not null before obtaining a reference to the `UserDao` and performing database operations, such as inserting a user into the database.

Note that `fallbackToDestructiveMigration` is used to indicate that the database should be recreated if a migration is not possible. You can use other migration strategies depending on your use case.

To make one coroutine wait for another coroutine to complete in Kotlin, you can use suspending functions and the `await()` method from the Kotlin Coroutines library.

Here's an example of how to make one coroutine wait for another coroutine using `async()` and `await()`:

```kotlin
// Define a suspending function to perform some task
suspend fun doSomeTask(): String {
    // Perform some task here
    delay(1000)
    return "Task completed"
}

// Call the suspending function using async and await
val job1 = CoroutineScope(Dispatchers.IO).async {
    doSomeTask()
}

val job2 = CoroutineScope(Dispatchers.IO).async {
    val result1 = job1.await()

    // Perform another task that depends on the result of job1
    return@async "Task 2 completed with result: $result1"
}

// Call job2 and wait for the result
val result2 = runBlocking {
    job2.await()
}
```

In this example, we define a suspending function `doSomeTask()` that simulates some long-running task using `delay()`. Next, we launch two coroutines using `async()` and the `await()` method.

The first coroutine, `job1`, calls the `doSomeTask()` function and returns the result as a string. The second coroutine, `job2`, waits for `job1` to complete using `await()`, and then performs another task that depends on the result of `job1`. Finally, we run the `job2` coroutine using `runBlocking()` and wait for the result.

By using `async()` and `await()`, we can make one coroutine wait for another coroutine to finish, without blocking the main thread.

To await the creation of a database before composing a view in Jetpack Compose, you can use a coroutine and the `LaunchedEffect` composable.

Here's an example of how to await the creation of a Room database before composing a view:

```kotlin
@Composable
fun MyComposable() {
    val context = LocalContext.current
    val myDatabase by remember(context) {
        mutableStateOf<MyDatabase?>(null)
    }

    // Launch a coroutine to create the database
    LaunchedEffect(Unit) {
        myDatabase = withContext(Dispatchers.IO) {
            Room.databaseBuilder(context, MyDatabase::class.java, "my-database-name")
                .build()
        }
    }

    // Wait for the database to be created before composing the view
    if (myDatabase != null) {
        // Compose your view here
    } else {
        // Show a loading indicator or a placeholder
    }
}
```

In this example, we define a composable function `MyComposable` that initializes a `MutableState` to hold the database instance. Then, we launch a coroutine using `LaunchedEffect` to create the database in the `IO` dispatcher. Once the database is created, we update the `MutableState` to hold the database instance.

In the composable function, we check if the database instance is not null before composing the view, using an `if` statement. If the database is not null, we can display the content of the view. Otherwise, we can display a loading indicator or a placeholder.

By using `LaunchedEffect` and a coroutine, we can make a composable function await the creation of a Room database before composing the view.

To make a field in a ViewModel await the creation of a Room database before fetching data, you can use a coroutine and the `onStart()` lifecycle method from the ViewModel.

Here's an example of how to make a ViewModel field await the creation of a database:

```kotlin
class MyViewModel(application: Application) : AndroidViewModel(application) {
    private var myDatabase: MyDatabase? = null
