To create a mountain in C++ using OpenGL, we can use the following example code. This example uses a combination of geometric primitives, transformation functions, and random height values to create a simple mountain landscape.

```cpp
#include <iostream>
#include <ctime>
#include <cstdlib>
#include <GL/glut.h>

// Define the dimensions of the mountain
constexpr int GRID_SIZE = 100;
constexpr float GRID_LENGTH = 1.0f;
constexpr float MAX_HEIGHT = 10.0f;

// Generate and store the height values
float height[GRID_SIZE][GRID_SIZE];

void initMountain() {
    std::srand(static_cast<unsigned int>(std::time(0)));

    for (int i = 0; i < GRID_SIZE; ++i) {
        for (int j = 0; j < GRID_SIZE; ++j) {
            height[i][j] = (std::rand() / (static_cast<float>(RAND_MAX))) * MAX_HEIGHT;
        }
    }
}

void drawMountain() {
    for (int i = 0; i < GRID_SIZE - 1; ++i) {
        for (int j = 0; j < GRID_SIZE - 1; ++j) {
            glBegin(GL_TRIANGLE_STRIP);
            glColor3f(0.0f, 0.5f, 0.0f);

            glVertex3f(i * GRID_LENGTH, j * GRID_LENGTH, height[i][j]);
            glVertex3f(i * GRID_LENGTH, (j + 1) * GRID_LENGTH, height[i][j + 1]);
            glVertex3f((i + 1) * GRID_LENGTH, j * GRID_LENGTH, height[i + 1][j]);
            glVertex3f((i + 1) * GRID_LENGTH, (j + 1) * GRID_LENGTH, height[i + 1][j + 1]);

            glEnd();
        }
    }
}

void display() {
    // Initialize and clear the buffer
    glClearColor(0.0f, 0.8f, 1.0f, 1.0f);
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    glLoadIdentity();

    // Position and orient the camera
    glTranslatef(-GRID_SIZE / 2.0f, -GRID_SIZE / 2.0f, -50.0f);
    glRotatef(75.0f, 1.0f, 0.0f, 0.0f);
    glRotatef(-45.0f, 0.0f, 1.0f, 0.0f);

    drawMountain();

    // Flush the contents to the display
    glFlush();
    glutSwapBuffers();
}

void init() {
    glEnable(GL_DEPTH_TEST);
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluPerspective(60.0, 1.0, 1.0, 1000.0);
    glMatrixMode(GL_MODELVIEW);
}

int main(int argc, char** argv) {
    initMountain();
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_RGBA | GLUT_DEPTH | GLUT_DOUBLE);
    glutInitWindowSize(800, 800);
    glutCreateWindow("Mountain Example in OpenGL");

    init();
    glutDisplayFunc(display);
    glutMainLoop();

    return 0;
}
